Object.assign(window.TEM8_DICTIONARY, {"lattice":{"media":{"uk":"media/uk/lattice__gb_1.mp3","us":"media/us/lattice__us_1.mp3"},"oxford":{"phon":"ˈlætɪs","pos":"noun","senses":[{"en":"a structure that is made of thin, narrow pieces of wood or metal that cross over each other with spaces that are like diamonds in shape between them, used, for example, as a fence; any structure or pattern like this","cn":"格子木架，格子金属架，格栅（用作篱笆等）；斜条结构；斜格图案","ex":{"en":"a low wall of stone latticework","cn":"石砌格构的矮墙"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"格子木架；斜条格构","en":"A lattice is a pattern or structure made of strips of wood or another material which cross over each other diagonally leaving holes in between.","ex":{"en":"We were crawling along the narrow steel lattice of the bridge.","cn":"我们沿着桥上狭窄的钢制格架往前爬。"}}]},"examples":[{"en":"a low wall of stone latticework","cn":"石砌格构的矮墙"},{"en":"a lattice of branches","cn":"树枝篱笆"}]},"languid":{"media":{"uk":"media/uk/languid__gb_1.mp3","us":"media/us/languid__us_1.mp3"},"oxford":{"phon":"ˈlæŋɡwɪd","pos":"adjective","senses":[{"en":"moving slowly in an attractive way, not needing energy or effort","cn":"慢悠悠的；慵懒的","ex":{"en":"a languid wave of the hand","cn":"懒洋洋一挥手"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"无精打采的；懒洋洋的；倦怠的","en":"If you describe someone as languid, you mean that they show little energy or interest and are very slow and casual in their movements.","ex":{"en":"To his delight a familiar, tall, languid figure lowered itself down the steps of a club.","cn":"看到一个熟悉的高大身影沿着俱乐部的台阶无精打采地走下来，他高兴极了。"}}]},"examples":[{"en":"a languid afternoon in the sun","cn":"阳光下一个懒洋洋的下午"},{"en":"He moved languidly across the room.","cn":"他慢悠悠地穿过房间。"}]},"largely":{"media":{"uk":"media/uk/largely__gb_1.mp3","us":"media/us/largely__us_1.mp3"},"oxford":{"phon":"ˈlɑːdʒli","pos":"adverb","senses":[{"en":"to a great extent; mostly or mainly","cn":"在很大程度上；多半；主要地","ex":{"en":"The manager was largely responsible for the team’s victory.","cn":"该队获胜主要仰赖主教练。"}}]},"collins":{"senses":[{"pos":"ADV-GRADED 副词","cn":"大致上；总体上；一般地说","en":"You use largely to say that a statement is not completely true but is mostly true.","ex":{"en":"The fund is largely financed through government borrowing","cn":"该基金大致上由政府借款支持。"}},{"pos":"ADV 副词","cn":"（用于说明原因）主要地","en":"Largely is used to introduce the main reason for a particular event or situation.","ex":{"en":"Retail sales dipped 6/10ths of a percent last month, largely because Americans were buying fewer cars","cn":"上月零售额下降了千分之六，主要是因为美国人买汽车少了。"}}]},"examples":[{"en":"He resigned largely because of the stories in the press.","cn":"他的辞职多半是因为新闻界的一些报道。"},{"en":"the manager who is largely responsible for the team's victory","cn":"对该队获胜起主要作用的经理"}]},"last":{"media":{"uk":"media/uk/last__gb_1.mp3","us":"media/us/last__us_1.mp3"},"oxford":{"phon":"lɑːst","pos":"determiner","senses":[{"en":"happening or coming after all other similar things or people","cn":"最后的；最末的；末尾的","ex":{"en":"We caught the last bus home.","cn":"我们赶上了回家的末班公共汽车。"}},{"en":"most recent","cn":"最近的；上一个的","g":"[only before noun]","ex":{"en":"last night/Tuesday/month/summer/year","cn":"昨晚；上个星期二；上个月；去年夏季；去年"}},{"en":"that is the only one that remains","cn":"仅剩的；最后的","g":"[only before noun]","ex":{"en":"This is our last bottle of water.","cn":"这是我们最后的一瓶水了。"}},{"en":"used to emphasize that somebody/something is the least likely or suitable","cn":"（强调）最不可能的，最不适当的","ex":{"en":"The last thing she needed was more work.","cn":"她最不需要的就是更多的工作。"}},{"en":"after anyone or anything else; at the end","cn":"最后；最终；终结","ex":{"en":"He came last in the race.","cn":"这次赛跑他得了最后一名。"},"pos":"adverb"},{"en":"most recently","cn":"最新；最近；上一次","ex":{"en":"When did you see him last?","cn":"你最后一次是什么时候见过他？"},"pos":"adverb"},{"en":"the person or thing that comes or happens after all other similar people or things","cn":"最后来的人（或发生的事）","ex":{"en":"Sorry I'm late—am I the last?","cn":"对不起，我来晚了。我是最后到的人吗？"},"pos":"noun"},{"en":"the only part or items that remain of something","cn":"仅剩下的部分（或几个）","ex":{"en":"These are the last of our apples.","cn":"这是我们最后剩下的几个苹果。"},"pos":"noun"},{"en":"the latest","cn":"最新事物；最新消息","g":"[singular]","ex":{"en":"That was the last I heard of him.","cn":"那是我最后一次听到他的消息。"},"pos":"noun"},{"en":"the least likely","cn":"最不可能的","ex":{"en":"Known for their self-sufficiency, fishermen would be the last to admit to mental strain.","cn":"渔民以自给自足著称，最不可能承认有精神压力。"},"pos":"noun"},{"en":"to continue for a particular period of time","cn":"持续；继续；延续","g":"[intransitive]","ex":{"en":"Each game lasts about an hour.","cn":"每场比赛约一小时。"},"pos":"verb"},{"en":"to continue to exist or to function well","cn":"继续存在；持续起作用；持久","g":"[intransitive, transitive]","ex":{"en":"This weather won't last.","cn":"这种天气持续不了多久。"},"pos":"verb"},{"en":"to survive something or manage to stay in the same situation, despite difficulties","cn":"（在困境等中）坚持下去；熬过（困境等）","g":"[intransitive, transitive]","ex":{"en":"She won't last long in that job.","cn":"她那份工作干不了多久。"},"pos":"verb"},{"en":"to be enough for somebody to use, especially for a particular period of time","cn":"够用，足够维持（尤指某段时间）","g":"[intransitive, transitive]","ex":{"en":"Will the coffee last out till next week?","cn":"咖啡够喝到下周吗？"},"pos":"verb"},{"en":"a block of wood or metal in the shape of a foot, used in making and repairing shoes","cn":"鞋楦","pos":"noun"}]},"collins":{"senses":[{"pos":"DET 限定词","cn":"（表示最近过去的）刚过去的星期五/昨晚/去年","en":"You use last in expressions such as last Friday ,last night, and last year to refer, for example, to the most recent Friday, night, or year.","ex":{"en":"I got married last July","cn":"我在刚过去的7月里结了婚。"}},{"pos":"ADJ 形容词","cn":"最近的；最近一次的","en":"The last event, person, thing, or period of time is the most recent one.","ex":{"en":"Much has changed since my last visit","cn":"从我上次去到现在，很多事情已经变了。"}},{"pos":"ADV 副词","cn":"上次；最近一次","en":"If something last happened on a particular occasion, that is the most recent occasion on which it happened.","ex":{"en":"When were you there last?","cn":"你上次去是什么时候？"}},{"pos":"ORD 序数词","cn":"最后的；最末的","en":"The last thing, person, event, or period of time is the one that happens or comes after all the others of the same kind.","ex":{"en":"This is his last chance as prime minister.","cn":"这是他作为首相的最后机会。"}},{"pos":"ADV 副词","cn":"最后地；最末地","en":"If you do something last, you do it after everyone else does, or after you do everything else.","ex":{"en":"I testified last","cn":"我最后一个作证。"}},{"pos":"PRON 代词","cn":"最后的人","en":"If you are the last to do or know something, everyone else does or knows it before you.","ex":{"en":"She was the last to go to bed","cn":"她最后一个上床。"}},{"pos":"ADJ 形容词","cn":"最后剩下的；最末的","en":"Last is used to refer to the only thing, person, or part of something that remains.","ex":{"en":"Jed nodded, finishing off the last piece of pizza.","cn":"杰德点点头，把最后一块比萨饼吃完。"}},{"pos":"ADJ 形容词","cn":"（竞赛中）最后留下的，排位在前的","en":"You use last before numbers to refer to a position that someone has reached in a competition after other competitors have been knocked out.","ex":{"en":"Sampras reached the last four at Wimbledon.","cn":"桑普拉斯杀入了温布尔登四强。"}},{"pos":"ADJ 形容词","cn":"最不想要的；最不可能的","en":"You can use last to indicate that something is extremely undesirable or unlikely.","ex":{"en":"The last thing I wanted to do was teach","cn":"我最不想干的事情就是教书。"}},{"pos":"PRON 代词","cn":"最后一次；最末一次","en":"The last you see of someone or the last you hear of them is the final time that you see them or talk to them.","ex":{"en":"She disappeared shouting, 'To the river, to the river!' And that was the last we saw of her","cn":"她高喊着“往河里去，往河里去！”然后就消失了。那是我们最后一次看到她的情形。"}},{"pos":"VERB 动词","cn":"持续，延续，维持（一段时间）","en":"If an event, situation, or problem lasts for a particular length of time, it continues to exist or happen for that length of time.","ex":{"en":"The marriage had lasted for less than two years","cn":"这段婚姻维持了不到两年。"}},{"pos":"VERB 动词","cn":"够用，保持可用状态（一段时间）","en":"If something lasts for a particular length of time, it continues to be able to be used for that time, for example because there is some of it left or because it is in good enough condition.","ex":{"en":"You only need a very small blob of glue, so one tube lasts for ages","cn":"每次只需一点点胶水而已，因此一管可以用很长时间。"}},{"pos":"VERB 动词","cn":"支持完；熬过；拖过","en":"You can use last in expressions such as last the game ,last the course, and last the week, to indicate that someone manages to take part in an event or situation right to the end, especially when this is very difficult for them.","ex":{"en":"They wouldn't have lasted the full game","cn":"他们本不可能撑完整场比赛的。"}},{"pos":"PHRASE 短语","cn":"终于；最后；到底","en":"If you say that something has happened at last or at long last you mean it has happened after you have been hoping for it for a long time.","ex":{"en":"I'm so glad that we've found you at last!","cn":"我们终于找到你了，我真是太高兴了！"}},{"pos":"PHRASE 短语","cn":"前天晚上／ 上上次选举／上上任领导人","en":"You use expressions such as the night before last ,the election before last and the leader before last to refer to the period of time, event, or person that came immediately before the most recent one in a series.","ex":{"en":"It was the dog he'd heard the night before last","cn":"他前晚听到的是狗叫声。"}},{"pos":"PHRASE 短语","cn":"气绝；断气；咽气","en":"If someone breathes their last, they die."},{"pos":"PHRASE 短语","cn":"倒数第二／倒数第三／ 倒数第四","en":"You can use phrases such as the last but one, the last but two, or the last but three, to refer to the thing or person that is, for example, one, two, or three before the final person or thing in a group or series.","ex":{"en":"It's the last but one day in the athletics programme","cn":"那是田径比赛结束的前一天。"}},{"pos":"PHRASE 短语","cn":"所有；全部","en":"You use every last to emphasize that you are talking about all the people or things in a group or all the parts of something.","ex":{"en":"I'd spent all I had, every last penny","cn":"我把钱全部花光了，一分不剩。"}},{"pos":"PHRASE 短语","cn":"（需要裁员时首先解雇新员工的）“后进先出”原则","en":"The expression last in, first out is used to say that the last person who started work in an organization should be the first person to leave it, if fewer people are needed.","ex":{"en":"Workers will go on a 'last in, first out' basis.","cn":"对工人的裁员原则是“后进先出”。"}},{"pos":"PHRASE 短语","cn":"我/她最近一次听到有关…的消息；最新消息","en":"You can use expressions such as the last I heard and the last she heard to introduce a piece of information that is the most recent that you have on a particular subject.","ex":{"en":"The last I heard, Joe and Irene were still happily married.","cn":"我最近一次听说时，乔和艾琳仍然是一对快乐的夫妻。"}},{"pos":"PHRASE 短语","cn":"把…留到最后","en":"If you leave something or someone until last, you delay using, choosing, or dealing with them until you have used, chosen, or dealt with all the others.","ex":{"en":"I have left my best wine until last","cn":"我把最好的酒留到了最后。"}},{"pos":"PHRASE 短语","cn":"不再见到某人","en":"If you see the last of someone, you do not expect to see them or deal with them again.","ex":{"en":"I honestly thought I'd seen the last of you.","cn":"老实说我以为再也不用见到你了。"}},{"pos":"PHRASE 短语","cn":"贯穿（全书、整部电影或整件事情）","en":"If you say that something goes on happening to the last, you mean that it happens throughout the whole of a book, film, or event.","ex":{"en":"...a highly readable political thriller with plenty of twists of plot to keep you guessing to the last.","cn":"一部可读性极强的政治惊悚小说，情节峰回路转，不到最后一刻绝对猜不中结局"}},{"pos":"PHRASE 短语","cn":"一直，始终（为某一类人）","en":"If you say that someone is a particular kind of person to the last, you are emphasizing that they continue to be that kind of person.","ex":{"en":"A gentleman to the last, he did not run, but merely attempted to stroll away","cn":"他始终保持绅士风度，没有拔脚就跑，只是试图移步走开。"}},{"pos":"PHRASE 短语","cn":"（表示全部包括在内）任何一丝细节/ 每一个人","en":"You use expressions such as to the last detail and to the last man to indicate that a plan, situation, or activity includes every single person, thing, or part involved.","ex":{"en":"Every movement, no matter how casual and spontaneous, needs to be worked out to the last detail","cn":"对每一个动作，无论它显得多么随意和无意识，都不能放过一丝细节。"}},{"pos":"","cn":"","en":"last breath→see: ; to have the last laugh→see: ; last-minute→see: ; someone's last stand→see: ; the last straw→see: ; last thing→see: ;"},{"pos":"","cn":"","en":"相关词组：last out"}]},"examples":[{"en":"Last but not least, I'd like to thank all the catering staff.","cn":"最后但同样重要的是，我要感谢所有的餐饮工作人员。"},{"en":"The last I heard he was still working at the garage.","cn":"我最近听到的消息是他还在汽车修理厂工作。"}]},"lasting":{"media":{"uk":"media/uk/lasting__gb_1.mp3","us":"media/us/lasting__us_1.mp3"},"oxford":{"phon":"ˈlɑːstɪŋ","pos":"adjective","senses":[{"en":"continuing to exist or to have an effect for a long time","cn":"继续存在的；持久的；耐久的","ex":{"en":"Her words left a lasting impression on me.","cn":"她的话给我留下了难忘的印象。"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"持续的；持久的；长久的","en":"You can use lasting to describe a situation, result, or agreement that continues to exist or have an effect for a very long time.","ex":{"en":"We are well on our way to a lasting peace","cn":"我们已在实现持久和平上取得很大进展。"}}]},"examples":[{"en":"I formed several lasting friendships at college.","cn":"我在大学与几个同学建立了牢固的友谊。"},{"en":"Her words left a lasting impression on me.","cn":"她的话给我留下了难忘的印象。"}],"base":"last"},"launch":{"oxford":{"phon":"lɔːntʃ","pos":"verb","senses":[{"en":"to start an activity, especially an organized one","cn":"开始从事，发起，发动（尤指有组织的活动）","g":"[transitive]","ex":{"en":"The government recently launched a national road safety campaign.","cn":"政府最近发起了全国道路安全运动。"}},{"en":"to make a product or service available to the public for the first time; to become available for the first time","cn":"（首次）上市，发行，推出","g":"[transitive, intransitive]","ex":{"en":"The company plans to launch the service to coincide with the World Cup this summer.","cn":"该公司计划在今年夏天的世界杯时推出这项服务。"}},{"en":"to put a ship or boat into the water, especially one that has just been built","cn":"使（船，尤指新船）下水","g":"[transitive]","ex":{"en":"The Navy is to launch a new warship today.","cn":"海军今天有一艘新军舰要下水。"}},{"en":"to send something such as a spacecraft, weapon, etc. into space, into the sky or through water","cn":"发射；把（航天器、武器等）发射升空；水中发射","g":"[transitive]","ex":{"en":"to launch a missile/rocket","cn":"发射导弹／火箭"}},{"en":"to criticize somebody/something or protest strongly","cn":"严厉批评；严重抗议","g":"[transitive]","ex":{"en":"He launched a biting attack on the senior management.","cn":"他对高层管理人员发起了猛烈的攻击。"}},{"en":"to jump forwards with a lot of force","cn":"猛扑向前","g":"[transitive]","lab":"figurative","ex":{"en":"Without warning he launched himself at me.","cn":"他突然向我猛扑过来。"}},{"en":"to start a computer program; (of a computer program) to start","cn":"启动（计算机程序）；（计算机程序）启动","g":"[transitive, intransitive]","lab":"computing","ex":{"en":"You can launch programs and documents from your keyboard.","cn":"从键盘可以启动程序、打开文档。"}},{"en":"the action of launching something","cn":"发起；发动；发射","g":"[usually singular]","ex":{"en":"a missile/rocket launch","cn":"导弹／火箭发射"},"pos":"noun"},{"en":"an event at which something is made available to the public for the first time","cn":"首次上市；发行；推出","ex":{"en":"a book/product launch","cn":"图书的发行；产品的上市"},"pos":"noun"},{"en":"a large boat with a motor","cn":"大型汽艇；机动大舢板；交通艇","ex":{"en":"one of the world's largest ocean-going launch platforms","cn":"全世界最大的远洋发射平台之一"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"发射（火箭、导弹或卫星）","en":"To launch a rocket, missile, or satellite means to send it into the air or into space.","ex":{"en":"NASA plans to launch a satellite to study cosmic rays","cn":"美国国家航空航天局计划发射一颗卫星上天，对宇宙射线进行研究。"}},{"pos":"VERB 动词","cn":"使（船）下水；使（新船）首次下水","en":"To launch a ship or a boat means to put it into water, often for the first time after it has been built.","ex":{"en":"There was no time to launch the lifeboats because the ferry capsized with such alarming speed.","cn":"渡轮瞬间倾覆，根本没时间放救生艇下水。"}},{"pos":"VERB 动词","cn":"开展（重大活动）；发起，发动（军事袭击等）","en":"To launch a large and important activity, for example a military attack, means to start it.","ex":{"en":"Heavy fighting has been going on after the guerrillas had launched their offensive","cn":"游击队发起攻击后，激烈的战斗一直持续不断。"}},{"pos":"VERB 动词","cn":"推出，发布（新产品）","en":"If a company launches a new product, it makes it available to the public.","ex":{"en":"Crabtree & Evelyn has just launched a new jam, Worcesterberry Preserve","cn":"瑰珀翠刚推出一款新果酱——伍斯特浆果果酱。"}},{"pos":"N-COUNT 可数名词","cn":"（在江河、湖泊和港口载人的）大型汽艇","en":"A launch is a large motorboat that is used for carrying people on rivers and lakes and in harbours.","ex":{"en":"The captain was on the deck of the launch, steadying the boat for the pilot","cn":"船长站在汽艇甲板上为领航员保向。"}},{"pos":"","cn":"","en":"相关词组：launch into"}]},"media":{"uk":"media/uk/launch__gb_1.mp3","us":"media/us/launch__us_1.mp3"},"examples":[{"en":"He launched into a lengthy account of his career.","cn":"他开始罗罗嗦嗦地讲述自己的工作经历。"},{"en":"to launch an appeal/an inquiry/an investigation/a campaign","cn":"开始上诉/质询/调查/一场运动"}]},"landscape":{"media":{"uk":"media/uk/landscape__gb_1.mp3","us":"media/us/landscape__us_1.mp3"},"oxford":{"phon":"ˈlændskeɪp","pos":"noun","senses":[{"en":"everything you can see when you look across a large area of land, especially in the country","cn":"（陆上，尤指乡村的）风景，景色","g":"[countable, usually singular]","ex":{"en":"the woods and fields that are typical features of the English landscape","cn":"具有典型英格兰风景特征的森林与田野"}},{"en":"a painting of a view of the countryside; this style of painting","cn":"乡村风景画；乡村风景画的风格","g":"[countable, uncountable]","lab":"US English","ex":{"en":"an artist famous for his landscapes","cn":"以风景画闻名的画家"}},{"en":"the characteristic features of an area of activity","cn":"风貌；景象","g":"[countable, usually singular]","ex":{"en":"We can expect changes in the political landscape.","cn":"我们等着看政治舞台上的变化吧。"}},{"en":"the way of printing a document in which the top of the page is one of the longer sides","cn":"（文件的）横向打印格式","g":"[uncountable]","ex":{"en":"Select the landscape option when printing the file.","cn":"打印文件时选择横向打印格式选项。"}},{"en":"to improve the appearance of an area of land by changing the design and planting trees, flowers, etc.","cn":"对…做景观美化；给…做园林美化；美化…的环境","ex":{"en":"landscaped gardens","cn":"园林"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"（陆上）风景，自然景色","en":"The landscape is everything you can see when you look across an area of land, including hills, rivers, buildings, trees, and plants. →see usage note at:","ex":{"en":"...Arizona's desert landscape","cn":"亚利桑那的沙漠风光"}},{"pos":"N-COUNT 可数名词","cn":"形势；情形；情状","en":"A landscape is all the features that are important in a particular situation.","ex":{"en":"...a change in the political landscape.","cn":"政治形势的改变"}},{"pos":"N-COUNT 可数名词","cn":"山水风景画；乡村风景画","en":"A landscape is a painting which shows a scene in the countryside."},{"pos":"VERB 动词","cn":"对…作景观美化；给…作园林美化","en":"If an area of land is landscaped, it is changed to make it more attractive, for example by adding streams or ponds and planting trees and bushes.","ex":{"en":"The gravel pits have been landscaped and planted to make them attractive to wildfowl","cn":"砾石采掘坑已进行了景观美化并种上了草木，希望能吸引野禽的到来。"}}]},"examples":[{"en":"the bleak/rugged/dramatic, etc. landscape of the area","cn":"那个地区荒芜的景观、崎岖的地貌、引人入胜的风光等"},{"en":"the woods and fields that are typical features of the English landscape","cn":"具有典型英国风景特征的森林与田野"}]},"lap":{"media":{"uk":"media/uk/lap__gb_1.mp3","us":"media/us/lap__us_1.mp3","img":["media/ldoce/img/lap.jpg"]},"oxford":{"phon":"læp","pos":"noun","senses":[{"en":"the top part of your legs that forms a flat surface when you are sitting down","cn":"（坐着时的）大腿部","g":"[usually singular]","ex":{"en":"There's only one seat so you'll have to sit on my lap.","cn":"只有一个座位，你只好坐在我腿上了。"}},{"en":"one journey from the beginning to the end of a track used for running, etc.","cn":"（跑道等的）一圈","lab":"North American English","ex":{"en":"the fastest lap on record","cn":"创纪录的最快的一圈"}},{"en":"a section of a journey, or of a piece of work, etc.","cn":"（行程或工作等中的）一段，环节","ex":{"en":"They're off on the first lap of their round-the-world tour.","cn":"他们踏上环游世界的第一段行程。"}},{"en":"to touch something gently and regularly, often making a soft sound","cn":"（轻柔而有规律地）拍打","g":"[intransitive]","ex":{"en":"The waves lapped around our feet.","cn":"波浪轻轻地拍打着我们的脚。"},"pos":"verb"},{"en":"to drink something with quick movements of the tongue","cn":"舔食；舔着喝","g":"[transitive]","pos":"verb"},{"en":"to pass another runner on a track who is one or more laps behind you","cn":"领先…一圈（或数圈）","g":"[transitive]","ex":{"en":"She had already lapped most of the other runners.","cn":"她已经超过了大多数其他赛跑者。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（人坐着时的）大腿部","en":"If you have something on your lap when you are sitting down, it is on top of your legs and near to your body.","ex":{"en":"She waited quietly with her hands in her lap","cn":"她双手放在腿上静静等候。"}},{"pos":"N-COUNT 可数名词","cn":"（比赛中的）一圈","en":"In a race, a competitor completes a lap when they have gone round a course once.","ex":{"en":"...that last lap of the race","cn":"比赛最后一圈"}},{"pos":"VERB 动词","cn":"（比赛中）对…完成套圈","en":"In a race, if you lap another competitor, you go past them while they are still on the previous lap.","ex":{"en":"He was caught out while lapping a slower rider.","cn":"他在套圈超越一位落后的车手时出了错。"}},{"pos":"N-COUNT 可数名词","cn":"一段路程；一段行程","en":"A lap of a long journey is one part of it, between two points where you stop.","ex":{"en":"I had thought we might travel as far as Oak Valley, but we only managed the first lap of the journey.","cn":"我原以为我们最远能到达橡树谷，结果只走完了第一段路程。"}},{"pos":"VERB 动词","cn":"（水）轻拍，轻打","en":"When water laps against something such as the shore or the side of a boat, it touches it gently and makes a soft sound.","ex":{"en":"...the water that lapped against the pillars of the boathouse","cn":"轻拍着船屋支柱的海水"}},{"pos":"VERB 动词","cn":"（动物）舐，舔","en":"When an animal laps a drink, it uses short quick movements of its tongue to take liquid up into its mouth.","ex":{"en":"The cat lapped milk from a dish.","cn":"猫舔食盘中牛奶。"}},{"pos":"PHRASE 短语","cn":"（成败）难以预料，非人力所能左右","en":"If you say that a situation is in the lap of the gods, you mean that its success or failure depends entirely on luck or on things that are outside your control.","ex":{"en":"They had to stop the operation, so at that stage my life was in the lap of the gods.","cn":"他们不得不停止手术，所以那时的我只能听天由命。"}},{"pos":"PHRASE 短语","cn":"养尊处优；锦衣玉食","en":"If you say that someone lives in the lap of luxury, you mean that they live in conditions of great comfort and wealth.","ex":{"en":"We don't live in the lap of luxury, but we're comfortable.","cn":"我们的生活虽然并非锦衣玉食，也算是衣食无忧。"}},{"pos":"","cn":"","en":"相关词组：lap up"}]},"examples":[{"en":"We've nearly finished. We're on the last lap.","cn":"我们接近完工了，正在处理最后的一部分工作。"},{"en":"It's a terrible movie but audiences everywhere are lapping it up.","cn":"这部电影很差劲，可各地的观众却趋之若鹜。"}]},"la":{"media":{"uk":"media/uk/la__gb_1.mp3","us":"media/us/la__us_1.mp3"},"oxford":{"phon":"lɑː","pos":"noun","senses":[{"en":"the 6th note of a major scale","cn":"大调音阶的第 6 音"},{"en":"the city of Los Angeles","cn":"洛杉矶市","pos":"abbreviation"}]}},"labour":{"media":{"uk":"media/uk/labour__gb_1.mp3","us":"media/us/labour__us_1.mp3"},"oxford":{"phon":"ˈleɪbə(r)","pos":"noun","senses":[{"en":"work, especially physical work","cn":"劳动；（尤指）体力劳动","g":"[uncountable]","sc":"work","ex":{"en":"manual labour (= work using your hands)","cn":"体力劳动"}},{"en":"a task or period of work","cn":"任务；（一段时间的）工作","g":"[countable, usually plural]","lab":"formal","sc":"work","ex":{"en":"He was so exhausted from the day's labours that he went straight to bed.","cn":"他工作了一天疲惫不堪，便直接上床休息了。"}},{"en":"the people who work or are available for work in a country or company","cn":"（统称）劳工，工人；劳动力","g":"[uncountable]","sc":"people who work","ex":{"en":"forced/slave labour","cn":"强迫/奴役劳动"}},{"en":"the period of time or the process of giving birth to a baby","cn":"分娩期；分娩；生产","g":"[uncountable, countable, usually singular]","sc":"having baby","ex":{"en":"Jane was in labour for ten hours.","cn":"简分娩花了十个小时。"}},{"en":"the British Labour Party","cn":"英国工党","g":"[uncountable + singular or plural verb]","sc":"politics","ex":{"en":"He always votes Labour.","cn":"他老是投工党的票。"}},{"en":"to try very hard to do something difficult","cn":"努力做（困难的事）","g":"[intransitive]","sc":"struggle","ex":{"en":"He was in his study labouring away over some old papers.","cn":"他在书房里潜心研究一些旧材料。"},"pos":"verb"},{"en":"to do hard physical work","cn":"干苦力活","g":"[intransitive]","lab":"old-fashioned","sc":"work hard","ex":{"en":"We laboured all day in the fields.","cn":"我们在田地里辛勤劳动了一整天。"},"pos":"verb"},{"en":"to move with difficulty and effort","cn":"困难吃力地行进","g":"[intransitive]","sc":"move with difficulty","ex":{"en":"The horses laboured up the steep slope.","cn":"那些马费力地爬上了陡坡。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"（辛苦的）劳动，劳作；（通常指）体力劳动","en":"Labour is very hard work, usually physical work.","ex":{"en":"...the labour of seeding, planting and harvesting","cn":"播种、种植和收割的辛勤劳作"}},{"pos":"VERB 动词","cn":"（用手）劳动","en":"Someone who labours works hard using their hands.","ex":{"en":"...peasants labouring in the fields","cn":"在地里劳作的农民"}},{"pos":"VERB 动词","cn":"艰苦地做；吃力地做","en":"If you labour to do something, you do it with difficulty.","ex":{"en":"For twenty-five years now he has laboured to build a religious community.","cn":"他呕心沥血地建立一个宗教社区，至今已有25个年头。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"（总称）劳工，工人","en":"Labour is used to refer to the workers of a country or industry, considered as a group.","ex":{"en":"Latin America lacked skilled labour","cn":"拉丁美洲缺乏熟练工人。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"劳动成果","en":"The work done by a group of workers or by a particular worker is referred to as their labour .","ex":{"en":"Every man should receive a fair price for the product of his labour","cn":"每个人的劳动成果都应该获得合理的回报。"}},{"pos":"N-PROPER-COLL 专有集合名词","cn":"（英国）工党","en":"In Britain, people use Labour to refer to the Labour Party.","ex":{"en":"He believes that, historically, Labour has been most successful as the party that helped people get on in life","cn":"他相信一直以来工党在帮助人民改善生活方面表现最为出色。"}},{"pos":"ADJ 形容词","cn":"工党的；支持工党的","en":"A Labour politician or voter is a member of a Labour Party or votes for a Labour Party.","ex":{"en":"...a Labour MP","cn":"工党下院议员"}},{"pos":"VERB 动词","cn":"误以为；为…所蒙蔽","en":"If you labour under a delusion or misapprehension, you continue to believe something which is not true.","ex":{"en":"She laboured under the illusion that I knew what I was doing","cn":"她有一个错觉，以为我知道自己在做什么。"}},{"pos":"VERB 动词","cn":"一再重申；反复说明","en":"If you labour a point or an argument, you keep making the same point or saying the same thing, although it is unnecessary.","ex":{"en":"I don't want to labour the point but there it is.","cn":"我不想反复重申，但还是不得不说。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"分娩；临盆","en":"Labour is the last stage of pregnancy, in which the baby is gradually pushed out of the womb by the mother.","ex":{"en":"I thought the pains meant I was going into labour.","cn":"我还以为这些疼痛意味着我要生了呢。"}}]},"examples":[{"en":"He's still labouring under the impression that he's written a great book.","cn":"他仍然有这样的错觉，以为自己撰写了一部巨著。"},{"en":"He was so exhausted from the day's labours that he went straight to bed.","cn":"他工作了一天疲惫不堪，便直接上床休息了。"}]},"later":{"media":{"uk":"media/uk/later__gb_1.mp3","us":"media/us/later__us_1.mp3"},"oxford":{"phon":"ˈleɪtə(r)","pos":"adverb","senses":[{"en":"at a time in the future; after the time you are talking about","cn":"后来；以后；其后；随后","ex":{"en":"See you later.","cn":"回头见。"}},{"en":"a way of saying goodbye, used by young people","cn":"（年轻人告别时说）再见","lab":"British English also","ex":{"en":"Later, guys!","cn":"伙计们，再见！"}},{"en":"coming after something else or at a time in the future","cn":"后来的；以后的","ex":{"en":"Rembrandt's later works","cn":"伦勃朗的晚期作品"},"pos":"adjective"},{"en":"near the end of a period of time, life, etc.","cn":"接近末期的；晚年的","ex":{"en":"the later part of the seventeenth century","cn":"17 世纪末叶"},"pos":"adjective"}]},"collins":{"senses":[{"pos":"","cn":"（late的比较级）","en":"Later is the comparative of late."},{"pos":"ADV 副词","cn":"后来；以后；过后","en":"You use later to refer to a time or situation that is after the one that you have been talking about or after the present one.","ex":{"en":"He resigned ten years later","cn":"10年后他辞了职。"}},{"pos":"ADJ-COMPAR 形容词比较级形式","cn":"后来的；以后的","en":"You use later to refer to an event, period of time, or other thing which comes after the one that you have been talking about or after the present one.","ex":{"en":"At a later news conference, he said differences should not be dramatized","cn":"在后来的新闻发布会上，他说不应夸大分歧。"}},{"pos":"ADJ-COMPAR 形容词比较级形式","cn":"晚年的；后期的；末期的","en":"You use later to refer to the last part of someone's life or career or the last part of a period of history.","ex":{"en":"He found happiness in later life","cn":"他在晚年找到了幸福。"}},{"pos":"","cn":"","en":"sooner or later→see: ;"}]},"examples":[{"en":"This is discussed in more detail in a later chapter.","cn":"在后面的一章中对这一点有更详细的讨论。"},{"en":"The match has been postponed to a later date.","cn":"比赛已被推迟到以后的某个日期举行。"}]},"lack":{"media":{"uk":"media/uk/lack__gb_1.mp3","us":"media/us/lack__us_1.mp3"},"oxford":{"phon":"læk","pos":"noun","senses":[{"en":"the state of not having something or not having enough of something","cn":"缺乏；匮乏；短缺","ex":{"en":"a lack of understanding/knowledge","cn":"缺乏理解/知识"}},{"en":"to have none or not enough of something","cn":"没有；缺乏；不足；短缺","ex":{"en":"to lack confidence/experience/resources/power","cn":"缺乏信心／经验／资源／权力"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"缺乏；不足；没有","en":"If there is a lack of something, there is not enough of it or it does not exist at all.","ex":{"en":"Despite his lack of experience, he got the job","cn":"他虽然经验不足，但还是获得了这份工作。"}},{"pos":"V-ERG 及物/不及物动词","cn":"缺少；欠缺；没有","en":"If you say that someone or something lacks a particular quality or that a particular quality is lacking in them, you mean that they do not have any or enough of it.","ex":{"en":"It lacked the power of the Italian cars","cn":"它没有意大利轿车动力强劲。"}},{"pos":"PHRASE 短语","cn":"不乏；有的是","en":"If you say there is no lack of something, you are emphasizing that there is a great deal of it.","ex":{"en":"He said there was no lack of things for them to talk about","cn":"他说他们之间不缺谈资。"}}]},"examples":[{"en":"Some houses still lack basic amenities such as bathrooms.","cn":"有些住宅仍没有像卫生间这样的基本设施。"},{"en":"The trip was cancelled through lack of (= because there was not enough) interest.","cn":"因为缺乏兴趣这次旅行被取消了。"}]},"landes":{"oxford":{"phon":"lænd","pos":"noun","senses":[{"en":"the surface of the earth that is not sea","cn":"陆地；大地"},{"en":"an area of ground, especially of a particular type or used for a particular purpose （","cn":"尤指某类型或作某种用途的）地带，土地"}]},"media":{"uk":"media/uk/land__gb_1.mp3","us":"media/us/land__us_1.mp3"}},"lace":{"oxford":{"phon":"leɪs","pos":"noun","senses":[{"en":"a very thin material made from threads of cotton, silk, etc. that are made into a pattern with holes","cn":"网眼织物；花边；蕾丝","g":"[uncountable]","ex":{"en":"a lace handkerchief","cn":"蕾丝手帕"}},{"en":"a long thin piece of material like string that goes through the holes on a shoe and is used to fasten it","cn":"鞋带","g":"[countable]","lab":"North American English also","ex":{"en":"Your laces are undone.","cn":"你的鞋带松开了。"}},{"en":"to be fastened with laces; to fasten something with laces","cn":"由带子系紧；把…用带子系牢","g":"[intransitive, transitive]","ex":{"en":"She was wearing a dress that laced up at the side.","cn":"她穿着一件在侧面系带子的连衣裙。"},"pos":"verb"},{"en":"to put a lace through the holes in a shoe, a boot, etc.","cn":"给（鞋、靴等）穿鞋带","g":"[transitive]","pos":"verb"},{"en":"to add a small amount of alcohol, a drug, poison, etc. to a drink","cn":"给（饮料）掺（少量的酒、药、毒药等）","g":"[transitive]","ex":{"en":"He had laced her milk with rum.","cn":"他在她的牛奶里加了少量朗姆酒。"},"pos":"verb"},{"en":"to add a particular quality to a book, speech, etc.","cn":"（以…）润色（书、讲话等）","g":"[transitive]","ex":{"en":"Her conversation was laced with witty asides.","cn":"她交谈中穿插了一些俏皮的题外话。"},"pos":"verb"},{"en":"to twist something together with another thing","cn":"使编织（或交织、缠绕）在一起","g":"[transitive]","ex":{"en":"They sat with their fingers laced.","cn":"他们手指交叉着坐在那里。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"网眼织物；花边；蕾丝","en":"Lace is a very delicate cloth which is made with a lot of holes in it. It is made by twisting together very fine threads of cotton to form patterns.","ex":{"en":"She finally found the perfect gown, a beautiful creation trimmed with lace.","cn":"她终于找到了理想的礼服——一袭饰有蕾丝的美丽长裙。"}},{"pos":"N-COUNT 可数名词","cn":"（衣物的）系带；（尤指）鞋带","en":"Laces are thin pieces of material that are put through special holes in some types of clothing, especially shoes. The laces are tied together in order to tighten the clothing.","ex":{"en":"Barry was sitting on the bed, tying the laces of an old pair of running shoes.","cn":"巴里正坐在床上系他那双旧跑鞋的鞋带。"}},{"pos":"VERB 动词","cn":"用系带束紧;用鞋带系（鞋）","en":"If you lace something such as a pair of shoes, you tighten the shoes by pulling the laces through the holes, and usually tying them together.","ex":{"en":"I have a good pair of skates, but no matter how tightly I lace them, my ankles wobble.","cn":"我有一双不错的溜冰鞋，可是不管我把鞋带系得多紧，脚脖子那里还是空落落的。"}},{"pos":"VERB 动词","cn":"在（饮料或食物）里掺入（少量的酒、药等）","en":"To lace food or drink with a substance such as alcohol or a drug means to put a small amount of the substance into the food or drink.","ex":{"en":"She laced his food with sleeping pills.","cn":"她在他的食物里掺了安眠药。"}},{"pos":"VERB 动词","cn":"在（言谈或文章）里夹杂（某种话语）","en":"If you lace your speech or writing with words of a particular kind, you include a lot of those words in what you say or write.","ex":{"en":"Fred liked to lace his conversation with military terms.","cn":"弗雷德喜欢在谈话中时不时蹦几个军事术语。"}},{"pos":"VERB 动词","cn":"交叉（手指）","en":"If you lace your fingers together, you put the palms of your hands together and fold your fingers over, fitting the fingers of one hand between the fingers of the other.","ex":{"en":"He took to lacing his fingers together in an attempt to keep his hands still.","cn":"为了不让双手发颤，他十指紧扣。"}},{"pos":"","cn":"","en":"相关词组：lace up"}]},"media":{"img":["media/pic/fasteners_clothes_comp.jpg","media/thumb/lace.jpg"],"uk":"media/uk/lace__gb_1.mp3","us":"media/us/lace__us_1.mp3"},"examples":[{"en":"She was wearing a dress that laced up at the side.","cn":"她穿着一件在侧面系带子的连衣裙。"},{"en":"He had laced her milk with rum.","cn":"他在她的牛奶里加了少量朗姆酒。"}]},"labyrinth":{"media":{"uk":"media/uk/labyrinth__gb_1.mp3","us":"media/us/labyrinth__us_1.mp3"},"oxford":{"phon":"ˈlæbərɪnθ","pos":"noun","senses":[{"en":"a complicated series of paths, which it is difficult to find your way through","cn":"迷宫；曲径","lab":"figurative","ex":{"en":"We lost our way in the labyrinth of streets.","cn":"我们在迷宫式的街道上迷了路。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"迷宫；迷阵","en":"If you describe a place as a labyrinth, you mean that it is made up of a complicated series of paths or passages, through which it is difficult to find your way.","ex":{"en":"...the labyrinth of corridors.","cn":"迷宫般的走廊"}},{"pos":"N-COUNT 可数名词","cn":"错综复杂的事物；千头万绪的局面；盘根错节的情况","en":"If you describe a situation, process, or area of knowledge as a labyrinth, you mean that it is very complicated.","ex":{"en":"...a labyrinth of conflicting political and sociological interpretations.","cn":"错综复杂、相互矛盾的政治学与社会学诠释"}}]},"examples":[{"en":"We lost our way in the labyrinth of streets.","cn":"我们在迷宫式的街道上迷了路。"},{"en":"( figurative ) a labyrinth of rules and regulations","cn":"错综复杂的规章制度"}]},"laptop":{"oxford":{"phon":"ˈlæptɒp","pos":"noun","senses":[{"en":"a small computer that can work with a battery and be easily carried","cn":"笔记本计算机；笔记本电脑","ex":{"en":"I opened my laptop and started typing.","cn":"我打开笔记本电脑开始打字。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"便携式电脑；膝上（或手提）电脑","en":"A laptop or a laptop computer is a small portable computer.","ex":{"en":"She used to work at her laptop until four in the morning.","cn":"她从前经常用手提电脑一直工作到凌晨4点。"}}]},"media":{"img":["media/pic/computing_equipment_comp.jpg","media/thumb/laptop.jpg"],"uk":"media/uk/laptop__gb_1.mp3","us":"media/us/laptop__us_1.mp3"}},"lakes":{"lemma":"lake","media":{"uk":"media/uk/lake__gb_1.mp3","us":"media/us/lake__us_1.mp3"}},"laboratory":{"media":{"img":["media/pic/laboratory_equipment_comp.jpg","media/thumb/bunsenburner.jpg"],"uk":"media/uk/laboratory__gb_1.mp3","us":"media/us/laboratory__us_1.mp3"},"oxford":{"phon":"ləˈbɒrətri","pos":"noun","senses":[{"en":"a room or building used for scientific research, experiments, testing, etc.","cn":"实验室；实验大楼","ex":{"en":"a clinical/research laboratory","cn":"临床／研究实验室"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（用于科研的）实验室，研究室，实验楼","en":"A laboratory is a building or a room where scientific experiments, analyses, and research are carried out."},{"pos":"N-COUNT 可数名词","cn":"（学生使用的）实验室","en":"A laboratory in a school, college, or university is a room containing scientific equipment where students are taught science subjects such as chemistry."}]},"examples":[{"en":"laboratory experiments/tests","cn":"实验室的实验/测试"},{"en":"a research laboratory","cn":"研究实验室"}]},"lazily":{"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not liking work or physical activity, or not making any effort to do anything","cn":""},{"en":"lazy and not doing enough work. Idle sounds rather formal and is becoming old-fashioned. In everyday English, people usually use lazy","cn":""}]},"examples":[{"en":"the laziest boy in the class","cn":"","src":"ld"},{"en":"He felt too lazy to get out of bed.","cn":"","src":"ld"}],"media":{"uk":"media/uk/lazily__gb_1.mp3","us":"media/us/lazily__us_1.mp3"},"oxford":{"phon":"ˈleɪzɪli","pos":"adverb","senses":[{"en":"in a way that shows somebody is unwilling to work or be active","cn":"不愿工作地；懒散地；懒惰地","lab":"disapproving","ex":{"en":"We sat around lazily.","cn":"我们懒洋洋地坐在一起。"}},{"en":"in a way that does not show enough care","cn":"没下功夫地；粗枝大叶地；马虎地","lab":"disapproving","ex":{"en":"a lazily scripted, poorly constructed film","cn":"一部剧本懒惰、结构糟糕的电影"}},{"en":"in a way that is slow and relaxed","cn":"懒洋洋地","ex":{"en":"She woke up and stretched lazily.","cn":"她醒来伸了个懒腰。"}},{"en":"with slow movements","cn":"行进缓慢地；慢吞吞地","lab":"literary","ex":{"en":"The birds circled lazily above our heads.","cn":"鸟儿在我们头顶上懒洋洋地盘旋。"}}]}},"lain":{"lemma":"lie","media":{"uk":"media/uk/lain__gb_1.mp3","us":"media/us/lain__us_1.mp3"}},"latter":{"media":{"uk":"media/uk/latter__gb_1.mp3","us":"media/us/latter__us_1.mp3"},"oxford":{"phon":"ˈlætə(r)","pos":"adjective","senses":[{"en":"used to refer to the second of two things or people mentioned","cn":"（提及的两者中）后者的","ex":{"en":"He chose the latter option.","cn":"他选择了后者。"}},{"en":"nearer to the end of a period of time than the beginning","cn":"后半期的；后面的","ex":{"en":"the latter half of the year","cn":"下半年"}},{"en":"recent","cn":"最近的","ex":{"en":"In latter years, the population has grown a lot here.","cn":"这里的人口最近几年增长了很多。"}},{"en":"the second of two things or people mentioned","cn":"（提及的两者中）后者","ex":{"en":"He presented two solutions. The latter seems much better.","cn":"他提出了两个解决方案，后一个看起来要好得多。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"PRON 代词","cn":"（两者之间的）后者","en":"When two people, things, or groups have just been mentioned, you can refer to the second of them as the latter.","ex":{"en":"He tracked down his cousin and uncle. The latter was sick.","cn":"他追查到了堂弟和叔叔的下落，发现叔叔这时正在病中。"}},{"pos":"ADJ 形容词","cn":"（一个时期或事件）后一半的，接近终了的","en":"You use latter to describe the later part of a period of time or event.","ex":{"en":"He is getting into the latter years of his career","cn":"他正步入职业生涯的后半程。"}}]},"examples":[{"en":"The town has a concert hall and two theatres. The latter were both built in the 1950s.","cn":"这座城镇有一个音乐厅和两个剧院。这两个剧院都是在 20 世纪 50 年代建成的。"},{"en":"He presented two solutions. The latter seems much better.","cn":"他提出了两个解决方案，后一个看起来要好得多。"}]},"laundry":{"media":{"uk":"media/uk/laundry__gb_1.mp3","us":"media/us/laundry__us_1.mp3"},"oxford":{"phon":"ˈlɔːndri","pos":"noun","senses":[{"en":"clothes, sheets, etc. that need washing, that are being washed, or that have been washed recently","cn":"要（或正在）洗的衣物；刚洗好的衣物","g":"[uncountable]","ex":{"en":"a pile of clean/dirty laundry","cn":"一摞干净的／脏的衣物"}},{"en":"the process or the job of washing clothes, sheets, etc.","cn":"洗衣物；洗衣物的活","g":"[uncountable, singular]","ex":{"en":"Have you done the laundry yet?","cn":"你洗完衣服了吗？"}},{"en":"a business or place where you send sheets, clothes, etc. to be washed","cn":"洗衣店；洗衣房","g":"[countable]","ex":{"en":"the hospital laundry","cn":"医院洗衣房"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"将要（或正在）洗的衣物；刚洗好的衣物","en":"Laundry is used to refer to clothes, sheets, and towels that are about to be washed, are being washed, or have just been washed.","ex":{"en":"I'll do your laundry","cn":"我来帮你洗衣服。"}},{"pos":"N-COUNT 可数名词","cn":"洗衣公司；洗衣店","en":"A laundry is a firm that washes and irons clothes, sheets, and towels for people.","ex":{"en":"We had to have the washing done at the laundry.","cn":"我们得把衣服拿到洗衣店去洗。"}},{"pos":"N-COUNT 可数名词","cn":"洗衣间；洗衣房","en":"A laundry or a laundry room is a room in a house, hotel, or institution where clothes, sheets, and towels are washed.","ex":{"en":"He worked in the laundry at Oxford prison.","cn":"他在牛津监狱的洗衣房工作。"}},{"pos":"","cn":"","en":"to wash your dirty laundry in public→see: ;"}]},"examples":[{"en":"The hotel has a laundry service.","cn":"旅馆提供洗衣服务。"},{"en":"a pile of clean/dirty laundry","cn":"一摞干净的/脏的衣物"}]},"lands":{"lemma":"land","media":{"uk":"media/uk/land__gb_1.mp3","us":"media/us/land__us_1.mp3"}},"lady":{"media":{"uk":"media/uk/lady__gb_1.mp3","us":"media/us/lady__us_1.mp3"},"oxford":{"phon":"ˈleɪdi","pos":"noun","senses":[{"en":"a word used to mean ‘woman’ that some people, especially older people, consider is more polite","cn":"女士，女子（有些人，尤其是长者，认为这样称呼成年女子比较礼貌）","g":"[countable]","lab":"British English, old-fashioned，，","ex":{"en":"There's a lady waiting to see you.","cn":"有位女士等着要见你。"}},{"en":"a woman who is polite and well educated, has excellent manners and always behaves well","cn":"举止文雅且有教养的女子；淑女","g":"[countable]","ex":{"en":"His wife was a real lady.","cn":"他的妻子真是个娴雅的淑女。"}},{"en":"used when speaking to or about a girl or woman, especially somebody you do not know","cn":"（尤用于称呼或谈及不认识的女子）女士，小姐","g":"[countable, usually plural]","lab":"formal","ex":{"en":"Can I take your coats, ladies?","cn":"女士们，我可以替你们拿大衣吗？"}},{"en":"an informal way to talk to a woman, showing a lack of respect","cn":"（不尊重的非正式称呼）女人，女士","g":"[singular]","lab":"especially North American English","ex":{"en":"Listen, lady, don't shout at me.","cn":"听着，女士，别对我大喊大叫的。"}},{"en":"(in the UK) a woman belonging to a high social class","cn":"（英国）贵妇人，夫人，小姐","g":"[countable]","lab":"old-fashioned","ex":{"en":"the lords and ladies of the court","cn":"宫廷的贵族及夫人"}},{"en":"(in the UK) a title used by a woman who is a member of the nobility, or by somebody who has been given the title ‘lady’ as an honour. The wives and daughters of some members of the nobility and the wives of knights are also called ‘Lady’.","cn":"（对女贵族、女爵士、贵族成员的妻女或爵士妻子的称呼）夫人，女士，小姐","g":"[countable]","ex":{"en":"Lady Howe","cn":"豪夫人"}},{"en":"a toilet for women in a public building or place","cn":"女厕所；女卫生间；女洗手间；女盥洗室","g":"[uncountable]","lab":"British English","ex":{"en":"Could you tell me where the ladies is?","cn":"请问女卫生间在哪里？"}},{"en":"a title used to refer to Mary, the mother of Christ, especially in the Roman Catholic Church","cn":"（尤用于天主教）圣母","ex":{"en":"Our Lady of Lourdes","cn":"露德圣母"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（尤为表示礼貌或尊敬的指称）女士；女子","en":"You can use lady when you are referring to a woman, especially when you are showing politeness or respect.","ex":{"en":"She's a very sweet old lady","cn":"她是一位很和蔼的老太太。"}},{"pos":"N-VOC 称呼名词","cn":"女士们；小姐们","en":"You can say 'ladies' when you are addressing a group of women in a formal and respectful way.","ex":{"en":"Your table is ready, ladies, if you'd care to come through","cn":"你们的桌位已经准备好了，女士们，请跟我来。"}},{"pos":"N-COUNT 可数名词","cn":"（尤指旧时上层阶级的）贵妇，夫人，小姐","en":"A lady is a woman from the upper classes, especially in former times.","ex":{"en":"...the Empress and ladies of the Imperial Palace","cn":"皇后与皇宫里的贵妇们"}},{"pos":"N-TITLE 头衔名词","cn":"（在英国用作对女贵族或爵士妻子的称谓）夫人，小姐","en":"In Britain, Lady is a title used in front of the names of some female members of the nobility, or the wives of knights.","ex":{"en":"Cockburn's arrival coincided with that of Sir Iain and Lady Noble","cn":"科伯恩到时正好伊恩爵士和诺布尔夫人也来了。"}},{"pos":"N-COUNT 可数名词","cn":"淑女；端庄的女士","en":"If you say that a woman is a lady, you mean that she behaves in a polite, dignified, and graceful way.","ex":{"en":"His wife was great as well, beautiful-looking and a real lady","cn":"他妻子也很招人喜欢，样子俏丽，是位真正的淑女。"}},{"pos":"N-SING 单数名词","cn":"公共女厕；女洗手间","en":"People sometimes refer to a public toilet for women as the ladies .","ex":{"en":"At Temple station, Charlotte rushed into the Ladies.","cn":"一到坦普尔站，夏洛特立即冲进了女厕所。"}},{"pos":"N-VOC 称呼名词","cn":"（尤用于商店里或街上男子对不相识女子的称谓）女士，小姐","en":"'Lady' is sometimes used by men as a form of address when they are talking to a woman that they do not know, especially in shops and in the street.","ex":{"en":"What seems to be the trouble, lady?","cn":"您遇到什么麻烦了吗，小姐？"}}]},"examples":[{"en":"He was with an attractive young lady.","cn":"他与一位漂亮的年轻女子在一起。"},{"en":"Can I take your coats, ladies?","cn":"女士们，我可以替你们拿大衣吗？"}]},"lawn":{"media":{"uk":"media/uk/lawn__gb_1.mp3","us":"media/us/lawn__us_1.mp3"},"oxford":{"phon":"lɔːn","pos":"noun","senses":[{"en":"an area of ground covered in short grass in a garden or park, or used for playing a game on","cn":"草坪；草地","g":"[countable]","ex":{"en":"In summer we have to mow the lawn twice a week.","cn":"夏天我们每周得修剪草坪两次。"}},{"en":"a type of fine cotton or linen cloth used for making clothes","cn":"上等细棉布（或麻布）","g":"[uncountable]"}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"草坪；草地","en":"A lawn is an area of grass that is kept cut short and is usually part of someone's garden or backyard, or part of a park.","ex":{"en":"They were sitting on the lawn under a large beech tree.","cn":"他们坐在一棵高大的山毛榉树下的草坪上。"}}]},"examples":[{"en":"In summer we have to mow the lawn twice a week.","cn":"夏天我们每周得修剪草坪两次。"},{"en":"a croquet lawn","cn":"槌球场"}]},"lacking":{"media":{"uk":"media/uk/lacking__gb_1.mp3","us":"media/us/lacking__us_1.mp3"},"oxford":{"phon":"ˈlækɪŋ","pos":"adjective","senses":[{"en":"having none or not enough of something","cn":"没有；匮乏；缺乏；不足","ex":{"en":"She's not usually lacking in confidence.","cn":"她平时并不缺乏自信心。"}},{"en":"not present or not available","cn":"不在场；得不到","ex":{"en":"I feel there is something lacking in my life.","cn":"我觉得我的生活中缺少点什么。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"缺少的；不足的；没有的","en":"If something or someone is lacking in a particular quality, they do not have any of it or enough of it.","ex":{"en":"...if your hair is lacking in lustre and feeling dry","cn":"如果头发缺少光泽且干枯"}}]},"examples":[{"en":"He was taken on as a teacher but was found lacking (= was thought not to be good enough).","cn":"他获聘为教师，能力却显得一般。"},{"en":"I feel there is something lacking in my life.","cn":"我觉得我的生活中缺少点什么。"}],"base":"lack"},"lacy":{"media":{"uk":"media/uk/lacy__gb_1.mp3","us":"media/us/lacy__us_1.mp3"},"oxford":{"phon":"ˈleɪsi","pos":"adjective","senses":[{"en":"made of or looking like lace","cn":"网眼状的；蕾丝的；似蕾丝的","ex":{"en":"lacy underwear","cn":"蕾丝内衣"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"网眼织物的；蕾丝做的；带蕾丝的","en":"Lacy things are made from lace or have pieces of lace attached to them.","ex":{"en":"...lacy nightgowns.","cn":"蕾丝睡裙"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（尤指因娇柔）呈蕾丝状的，似蕾丝的","en":"Lacy is used to describe something that looks like lace, especially because it is very delicate.","ex":{"en":"...lacy ferns.","cn":"蕾丝般娇柔的蕨"}}]},"examples":[{"en":"lacy underwear","cn":"蕾丝内衣"},{"en":"a plant with delicate, lacy leaves","cn":"有细致网眼叶子的植物"}]},"landmark":{"media":{"uk":"media/uk/landmark__gb_1.mp3","us":"media/us/landmark__us_1.mp3"},"oxford":{"phon":"ˈlændmɑːk","pos":"noun","senses":[{"en":"something, such as a large building, that you can see clearly from a distance and that will help you to know where you are","cn":"陆标，地标（有助于识别所处地点的大建筑物等）","ex":{"en":"The Empire State Building is a familiar landmark on the New York skyline.","cn":"帝国大厦是人们熟悉的纽约空中轮廓线上的地标。"}},{"en":"an event, a discovery, an invention, etc. that marks an important stage in something","cn":"（标志重要阶段的）里程碑","ex":{"en":"The ceasefire was seen as a major landmark in the fight against terrorism.","cn":"停火协定被看作是与恐怖主义斗争的重要里程碑。"}},{"en":"a building or a place that is very important because of its history, and that should be preserved","cn":"有历史意义的建筑物（或遗址）","lab":"especially North American English","ex":{"en":"The residents are seeking landmark status for the building.","cn":"居民们正在为大楼争取地标身分。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"地标；陆标","en":"A landmark is a building or feature which is easily noticed and can be used to judge your position or the position of other buildings or features.","ex":{"en":"The Ambassador Hotel is a Los Angeles landmark.","cn":"国宾大饭店是洛杉矶的地标性建筑之一。"}},{"pos":"N-COUNT 可数名词","cn":"里程碑；转折点","en":"You can refer to an important stage in the development of something as a landmark .","ex":{"en":"...a landmark arms control treaty","cn":"里程碑式的军备控制条约"}}]},"examples":[{"en":"The ceasefire was seen as a major landmark in the fight against terrorism.","cn":"停火协定被看作是与恐怖主义斗争的重要里程碑。"},{"en":"The Empire State Building is a familiar landmark on the New York skyline.","cn":"帝国大厦是纽约空中轮廓线中人们熟悉的地标。"}]},"laborers":{"lemma":"laborer"},"law":{"media":{"uk":"media/uk/law__gb_1.mp3","us":"media/us/law__us_1.mp3"},"oxford":{"phon":"lɔː","pos":"noun","senses":[{"en":"a rule that deals with a particular crime, agreement, etc.","cn":"（针对某项罪行、协议等的一条）法律，法规","g":"[countable]","lab":"informal","sc":"one rule","ex":{"en":"to pass a law (= officially make it part of the system of laws)","cn":"通过一项法律"}},{"en":"the whole system of rules that everyone in a country or society must obey","cn":"法律（体系）","g":"[uncountable]","lab":"humorous","sc":"system of rules","ex":{"en":"If they entered the building they would be breaking the law.","cn":"如果进入那栋大楼，他们就会触犯法律。"}},{"en":"a particular branch of the law","cn":"法规","g":"[uncountable]","sc":"system of rules","ex":{"en":"tax/employment law","cn":"税法；就业法"}},{"en":"the study of the law as a subject at university, etc.; the profession of being a lawyer","cn":"法学；法律学；律师业","g":"[uncountable]","lab":"North American English","sc":"subject/profession","ex":{"en":"a law student/professor","cn":"法学学生／教授"}},{"en":"used to refer to the police and the legal system","cn":"警方；法律机构","g":"[singular]","sc":"police","ex":{"en":"Jim is always getting into trouble with the law.","cn":"吉姆总是因惹事落到警察手里。"}},{"en":"the fact that something always happens in the same way in an activity or in nature","cn":"规律；法则；原理","g":"[countable]","sc":"in business/nature/science","ex":{"en":"The usual laws of supply and demand do not seem to apply in this case.","cn":"一般的供求规律似乎不适用于这种情况。"}},{"en":"a scientific rule that somebody has stated to explain a natural process","cn":"定律","g":"[countable]","sc":"in business/nature/science","ex":{"en":"the first law of thermodynamics","cn":"热力学第一定律"}},{"en":"one of the rules that controls an organization or activity","cn":"规则；规章；条例","g":"[countable]","sc":"of organization/activity","ex":{"en":"the laws of the Church","cn":"教会的戒律"}},{"en":"a rule for good behaviour or how you should behave in a particular place or situation","cn":"良好行为的准则；（某地或某场合下的）行为规范","g":"[countable]","sc":"of good behaviour","ex":{"en":"He frequently behaved as though moral laws did not exist.","cn":"他的所作所为常常无视道德准则的存在。"}}]},"collins":{"senses":[{"pos":"N-SING 单数名词","cn":"法律（体系）；法律界人士","en":"The law is a system of rules that a society or government develops in order to deal with crime, business agreements, and social relationships. You can also use the law to refer to the people who work in this system.","ex":{"en":"Obscene and threatening phone calls are against the law","cn":"猥亵和恐吓电话都是违法的。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"（用于指某一种法律）刑法/公司法","en":"Law is used to refer to a particular branch of the law, such as criminal law or company law.","ex":{"en":"He was a professor of criminal law at Harvard University law school","cn":"他是哈佛大学法学院的刑法学教授。"}},{"pos":"N-COUNT 可数名词","cn":"（针对某种协议、关系或罪行的）法律，法","en":"A law is one of the rules in a system of law which deals with a particular type of agreement, relationship, or crime.","ex":{"en":"...the country's liberal political asylum law","cn":"该国开明的政治庇护法"}},{"pos":"N-PLURAL 复数名词","cn":"（组织或活动的）规则，规章，条例","en":"The laws of an organization or activity are its rules, which are used to organize and control it.","ex":{"en":"...the laws of the Church of England","cn":"英国国教会的教规"}},{"pos":"N-COUNT 可数名词","cn":"准则；规矩；道理","en":"A law is a rule or set of rules for good behaviour which is considered right and important by the majority of people for moral, religious, or emotional reasons.","ex":{"en":"...inflexible moral laws.","cn":"不容改变的道德准则"}},{"pos":"N-COUNT 可数名词","cn":"规律；法则","en":"A law is a natural process in which a particular event or thing always leads to a particular result.","ex":{"en":"The laws of nature are absolute.","cn":"自然法则至高无上。"}},{"pos":"N-COUNT 可数名词","cn":"定律；定理","en":"A law is a scientific rule that someone has invented to explain a particular natural process.","ex":{"en":"...the law of gravity.","cn":"万有引力定律"}},{"pos":"N-UNCOUNT 不可数名词","cn":"司法界；法律行业","en":"Law or the law is all the professions which deal with Advising people about the law, representing people in court, or giving decisions and punishments.","ex":{"en":"A career in law is becoming increasingly attractive to young people","cn":"法律行业对年轻人的吸引力越来越大。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"法学","en":"Law is the study of systems of law and how laws work.","ex":{"en":"He came to Oxford and studied law","cn":"他来到牛津学习法律。"}},{"pos":"PHRASE 短语","cn":"凌驾于法律之上；高于法律","en":"If you accuse someone of thinking they are above the law, you criticize them for thinking that they are so clever or important that they do not need to obey the law.","ex":{"en":"One opposition member of parliament accuses the government of wanting to be above the law","cn":"议会一名反对党议员指责政府意图凌驾于法律之上。"}},{"pos":"PHRASE 短语","cn":"平均律","en":"The law of averages is the idea that something is sure to happen at some time, because of the number of times it generally happens or is expected to happen.","ex":{"en":"On the law of averages we just can't go on losing.","cn":"根据平均律，我们不会再输下去了。"}},{"pos":"PHRASE 短语","cn":"根据法律；依法","en":"If you have to do something by law or if you are not allowed to do something by law, the law states that you have to do it or that you are not allowed to do it.","ex":{"en":"By law all restaurants must display their prices outside","cn":"根据法律，所有餐厅都必须在店外明示用餐价格。"}},{"pos":"PHRASE 短语","cn":"诉诸法律；提起诉讼；打官司","en":"If you go to law, you go to court in order to get a legal judgment on a dispute.","ex":{"en":"He went to law and did not succeed in his claim against us.","cn":"他告上了法庭，但没有告赢我们。"}},{"pos":"PHRASE 短语","cn":"（自以为是地）发号施令","en":"If you say that someone lays down the law, you are critical of them because they give other people orders and they think that they are always right.","ex":{"en":"...traditional parents, who believed in laying down the law for their offspring.","cn":"认为应对子女发号施令的传统的家长们"}},{"pos":"PHRASE 短语","cn":"不通过法律自行解决，以暴代法（以惩罚他人或摆平某事）","en":"If someone takes the law into their own hands, they punish someone or do something to put a situation right, instead of waiting for the police or the legal system to take action.","ex":{"en":"The speeding motorist was pinned to the ground by angry locals who took the law into their own hands until police arrived.","cn":"愤怒的当地人以暴代法——将超速司机强行按在地上，直至警察赶来。"}},{"pos":"PHRASE 短语","cn":"（无视法律或惯例而）我行我素，自行其是","en":"If you say that someone is a law unto himself or herself, you mean that they behave in an independent way, ignoring laws, rules, or conventional ways of doing things.","ex":{"en":"Some of the landowners were a law unto themselves. There was nobody to check their excesses and they exploited the people.","cn":"某些土地所有者目无法纪。他们横行霸道，鱼肉乡民。"}},{"pos":"","cn":"","en":"Sod's law→see: ;"}]},"examples":[{"en":"Defence attorneys can use any means within the law to get their client off.","cn":"辩护律师可在法律许可的范围内利用任何手段为当事人脱罪。"},{"en":"Keep applying and by the law of averages you'll get a job sooner or later.","cn":"继续申请吧，根据平均律你迟早会找到工作的。"}]},"lawmaker":{"media":{"uk":"media/uk/lawmaker__gb_1.mp3","us":"media/us/lawmaker__us_1.mp3"},"oxford":{"phon":"ˈlɔːmeɪkə(r)","pos":"noun","senses":[{"en":"a politician who helps make the laws of a country","cn":"立法者","ex":{"en":"State lawmakers have been arguing over the new healthcare reform bill for months.","cn":"州立法部门几个月来一直在争论新医改法案。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"立法者","en":"A lawmaker is someone such as a politician who is responsible for proposing and passing new laws."}]}},"labelling":{"lemma":"label"},"lamp":{"media":{"img":["media/ldoce/img/lamp.jpg","media/pic/lamps_livingroom_comp.jpg"],"uk":"media/uk/lamp__gb_1.mp3","us":"media/us/lamp__us_1.mp3"},"oxford":{"phon":"læmp","pos":"noun","senses":[{"en":"a device that uses electricity, oil or gas to produce light","cn":"灯","lab":"British English","ex":{"en":"a desk/bedside lamp","cn":"台灯；床头灯"}},{"en":"an electrical device that produces rays of heat and that is used for medical or scientific purposes","cn":"（理疗用的）发热灯；（科学上用的）射线照射器","ex":{"en":"an infrared/ultraviolet lamp","cn":"红外线灯；紫外线灯"}},{"en":"to hit somebody very hard","cn":"重击；狂殴","ex":{"en":"The guy lamped me.","cn":"那家伙打得我不轻。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"灯","en":"A lamp is a light that works by using electricity or by burning oil or gas.","ex":{"en":"She switched on the bedside lamp","cn":"她打开床头灯。"}},{"pos":"N-COUNT 可数名词","cn":"（尤指治疗或美容用的）发热灯，照射灯","en":"A lamp is an electrical device which produces a special type of light or heat, used especially in medical or beauty treatment.","ex":{"en":"...a sun lamp.","cn":"太阳灯"}}]},"examples":[{"en":"I'd have lamped her one!","cn":"我本想狠狠地揍她一顿！"},{"en":"The guy lamped me.","cn":"那家伙打得我不轻。"}]},"laugh":{"media":{"uk":"media/uk/laugh__gb_1.mp3","us":"media/us/laugh__us_1.mp3"},"oxford":{"phon":"lɑːf","pos":"verb","senses":[{"en":"to make the sounds and movements of your face that show you think something is funny or silly","cn":"笑；发笑","g":"[intransitive, transitive]","lab":"British English","ex":{"en":"to laugh out loud","cn":"哈哈大笑"}},{"en":"used to say that you are in a very good position, especially because you have done something successfully","cn":"（尤因成功而）处于有利地位","g":"[intransitive]","lab":"informal","ex":{"en":"If we win the next game we'll be laughing.","cn":"要是赢了下一场比赛，我们就占优势了。"}},{"en":"the sound you make when you think that something is funny or silly","cn":"笑；笑声","g":"[countable]","ex":{"en":"to give a laugh","cn":"大笑一声"},"pos":"noun"},{"en":"an occasion or thing that is good fun","cn":"令人开心的时刻；引人发笑的事；笑料","g":"[singular]","lab":"informal","ex":{"en":"Come to the karaoke night—it should be a good laugh.","cn":"来参加卡拉 OK 晚会吧，一定会很开心的。"},"pos":"noun"},{"en":"a person who is fun to be with","cn":"引人发笑的人；逗笑好玩的人","g":"[singular]","ex":{"en":"Paula's a good laugh, isn't she?","cn":"葆拉是个活宝，是不是？"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"笑；大笑","en":"When you laugh, you make a sound with your throat while smiling and show that you are happy or amused. People also sometimes laugh when they feel nervous or are being unfriendly.","ex":{"en":"He was about to offer an explanation, but she was beginning to laugh","cn":"他正要解释，她却笑起来了。"}},{"pos":"VERB 动词","cn":"嘲笑；讥笑","en":"If people laugh at someone or something, they mock them or make jokes about them.","ex":{"en":"I thought they were laughing at me because I was ugly","cn":"我觉得他们嘲笑我是因为我长得丑。"}},{"pos":"PHRASE 短语","cn":"开玩笑；逗趣","en":"If you do something for a laugh or for laughs, you do it as a joke or for fun.","ex":{"en":"They were persuaded onstage for a laugh by their mates","cn":"他们被同伴们说服，上台一乐。"}},{"pos":"PHRASE 短语","cn":"引人发笑；逗笑","en":"If a person or their comment gets a laugh or raises a laugh, they make the people listening to them laugh.","ex":{"en":"If you can get a laugh by wearing a silly hat, you must have been born a comic","cn":"如果你戴一顶傻傻的帽子就能让人发笑，那你一定是天生的笑匠。"}},{"pos":"PHRASE 短语","cn":"好玩/ 开心/有点意思","en":"If you describe a situation as a laugh ,a good laugh, or a bit of a laugh, you think that it is fun and do not take it too seriously.","ex":{"en":"Working there's great. It's quite a good laugh actually","cn":"在那儿工作挺不错。说实在的，蛮好玩儿的。"}},{"pos":"PHRASE 短语","cn":"开心果；逗笑好玩的人","en":"If you describe someone as a laugh or a good laugh, you like them because they are amusing and fun to be with.","ex":{"en":"Mickey was a good laugh and great to have in the dressing room.","cn":"米基是个活宝，在更衣室里总是逗人笑个不停。"}},{"pos":"PHRASE 短语","cn":"（尤指经历了最初的苦恼不快后）觉得…可笑，对…一笑置之","en":"If you have a good laugh about something, you find it amusing and realize that it is funny, especially when the situation was at first upsetting.","ex":{"en":"We've both had a good laugh about the accident despite what's happened.","cn":"虽然出了意外，但我俩事后都一笑置之。"}},{"pos":"PHRASE 短语","cn":"笑到最后；取得最后胜利","en":"If you say that you have the last laugh, you mean that you become successful at something so that people who criticize or oppose you look foolish.","ex":{"en":"Des O'Connor is expecting to have the last laugh on his critics by soaring to the top of the Christmas hit parade.","cn":"德斯·奥康纳预计会飙升至圣诞畅销唱片排行榜的榜首，这将让他的批评者都笑不出来。"}},{"pos":"CONVENTION 惯用语","cn":"别让我笑掉大牙了；别逗了","en":"Some people reply to other people's comments or opinions by saying 'Don't make me laugh' when they disagree with them and think they are foolish or inaccurate.","ex":{"en":"Claire, a poisoner? Don't make me laugh — She was just a lousy cook.","cn":"克莱尔投毒？别逗了。她只不过厨艺很差罢了。"}},{"pos":"CONVENTION 惯用语","cn":"（对于困境或令人失望的境况）何妨一笑，还有可笑之处","en":"If you say 'you've got to laugh' or 'you have to laugh', you are trying to see the amusing side of a difficult or disappointing situation rather than being sad or angry about it.","ex":{"en":"The bikers have shown enough contempt of the law to ride their machines over police cars. 'You've got to laugh at their audacity,' said Mr Starkey.","cn":"摩托车党藐视法律，竟对警车玩起凌空飞车来。“牛气可嘉呀，”斯塔基先生说道。"}},{"pos":"","cn":"","en":"to laugh someone out of court→see: ; to laugh in someone's face→see: ; to laugh your head off→see: ; no laughing matter→see: ; to laugh all the way to the bank→see: ;"},{"pos":"","cn":"","en":"相关词组：laugh off"}]},"examples":[{"en":"Well, I'm sorry you've lost your shoes, but you've got to laugh, haven't you?","cn":"啊，真糟糕，你的鞋子丢了，可是这也挺逗的，是不是？"},{"en":"Come to the karaoke night — it should be a good laugh.","cn":"来参加卡拉 OK 晚会吧，一定会很开心的。"}]},"lantern":{"media":{"uk":"media/uk/lantern__gb_1.mp3","us":"media/us/lantern__us_1.mp3","img":["media/ldoce/img/lantern.jpg"]},"oxford":{"phon":"ˈlæntən","pos":"noun","senses":[{"en":"a lamp in a clear case, often a metal case with glass sides, and often with a handle, so that you can carry it outside","cn":"灯笼；提灯","ex":{"en":"The lantern hung from the roof.","cn":"灯笼挂在房顶上。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"灯笼；提灯","en":"A lantern is a lamp in a metal frame with glass sides and with a handle on top so you can carry it."}]}},"launched":{"lemma":"launch"},"laces":{"lemma":"lace"},"latest":{"media":{"uk":"media/uk/latest__gb_1.mp3","us":"media/us/latest__us_1.mp3"},"oxford":{"phon":"ˈleɪtɪst","pos":"adjective","senses":[{"en":"the most recent or newest","cn":"最近的；最新的","ex":{"en":"the latest craze/fashion/trend","cn":"最新时尚／款式／动向"}},{"en":"the most recent or the newest thing or piece of news","cn":"最新事物；最新消息","ex":{"en":"This is the latest in robot technology.","cn":"这是最新的机器人技术。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"","cn":"（late的最高级）","en":"Latest is the superlative of late."},{"pos":"ADJ-SUPERL 形容词最高级形式","cn":"最近的；最新的","en":"You use latest to describe something that is the most recent thing of its kind.","ex":{"en":"...her latest book","cn":"她的新书"}},{"pos":"ADJ-SUPERL 形容词最高级形式","cn":"最新式的；最现代的","en":"You can use latest to describe something that is very new and modern and is better than older things of a similar kind.","ex":{"en":"Crooks are using the latest laser photocopiers to produce millions of fake banknotes","cn":"犯罪分子正利用最新式的激光复印机制造数以百万计的假钞。"}},{"pos":"PHRASE 短语","cn":"最晚；至迟","en":"You use at the latest in order to indicate that something must happen at or before a particular time and not after that time.","ex":{"en":"She should be back by ten o'clock at the latest.","cn":"她最晚应该在10点前回来。"}}]},"examples":[{"en":"Applications should be in by next Monday at the latest.","cn":"最迟须于下星期一递交申请书。"},{"en":"This is the latest in robot technology.","cn":"这是最新的机器人技术。"}]},"landowner":{"oxford":{"phon":"ˈlændəʊnə(r)","pos":"noun","senses":[{"en":"a person who owns land, especially a large amount of land","cn":"土地拥有者；地主"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"土地所有者；（尤指）地主","en":"A landowner is a person who owns land, especially a large amount of land.","ex":{"en":"...rural communities involved in conflicts with large landowners.","cn":"与大地主发生冲突的农村社区"}}]},"media":{"uk":"media/uk/landowner__gb_1.mp3","us":"media/us/landowner__us_1.mp3"},"examples":[{"en":"the great landowning families","cn":"拥有大量土地的家族"},{"en":"private landownership","cn":"土地私有制"}]},"latin":{"oxford":{"phon":"ˈlætɪn","pos":"noun","senses":[{"en":"the language of ancient Rome and the official language of its empire","cn":"拉丁语","g":"[uncountable]"},{"en":"a person from countries where languages that have developed from Latin, such as Spanish, Portuguese, Italian or French, are spoken","cn":"拉丁人（来自拉丁语系国家，如西班牙、葡萄牙、意大利或法国）","g":"[countable]"},{"en":"music of a kind that came originally from Latin America, typically with strong dance rhythms","cn":"拉丁音乐（源自拉丁美洲，节奏感强，适于跳舞）","g":"[uncountable]"},{"en":"of or in the Latin language","cn":"拉丁语的；用拉丁语写成的","ex":{"en":"Latin poetry","cn":"拉丁语诗歌"},"pos":"adjective"},{"en":"connected with or typical of the countries or peoples using languages developed from Latin, such as Spanish, Portuguese, Italian or French","cn":"拉丁语系国家（或民族）的（如西班牙、葡萄牙、意大利或法国）；拉丁人的","ex":{"en":"a Latin temperament","cn":"拉丁人的气质"},"pos":"adjective"},{"en":"connected with or typical of Latin American music","cn":"拉丁音乐（风格）的","ex":{"en":"music with a Latin beat","cn":"拉丁节奏的音乐"},"pos":"adjective"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"拉丁语","en":"Latin is the language which the ancient Romans used to speak."},{"pos":"ADJ 形容词","cn":"（国家）操拉丁系语言的；拉丁语系国家的","en":"Latin countries are countries where Spanish, or perhaps Portuguese, Italian, or French, is spoken. You can also use Latin to refer to things and people that come from these countries.","ex":{"en":"Cuba was one of the least Catholic of the Latin countries","cn":"古巴是拉丁语系国家中天主教化程度最小的国家之一。"}},{"pos":"N-COUNT 可数名词","cn":"拉丁语系国家公民","en":"Latins are people who come from countries where Spanish, or perhaps Portuguese, Italian, or French, are spoken or whose families come from one of these countries.","ex":{"en":"They are role models for thousands of young Latins.","cn":"他们是千万拉丁青年的榜样。"}}]},"media":{"uk":"media/uk/latin__gb_1.mp3","us":"media/us/latin__us_1.mp3"},"examples":[{"en":"a Latin temperament","cn":"拉丁人的气质"},{"en":"Latin poetry","cn":"拉丁语诗歌"}]},"language":{"media":{"uk":"media/uk/language__gb_1.mp3","us":"media/us/language__us_1.mp3"},"oxford":{"phon":"ˈlæŋɡwɪdʒ","pos":"noun","senses":[{"en":"the system of communication in speech and writing that is used by people of a particular country or area","cn":"语言","g":"[countable]","sc":"of a country","ex":{"en":"the English language","cn":"英语"}},{"en":"the use by humans of a system of sounds and words to communicate","cn":"言语；说话；语言","g":"[uncountable]","sc":"communication","ex":{"en":"a qualification in language teaching","cn":"语言教学的资格"}},{"en":"a particular style of speaking or writing","cn":"某种类型的言语（或语言）","g":"[uncountable]","sc":"style of speaking/writing","ex":{"en":"spoken/written language","cn":"口语；书面语"}},{"en":"a way of expressing ideas and feelings using movements, symbols and sound","cn":"（用动作、符号和语音来表达思想感情的）表达方式，交际方式","g":"[uncountable, countable]","sc":"movements/symbols/sound","ex":{"en":"the language of mime","cn":"哑剧的手势语"}},{"en":"a system of symbols and rules that is used to operate a computer","cn":"计算机语言","g":"[countable, uncountable]","sc":"computing","ex":{"en":"a programming language","cn":"程序设计语言"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"语言；语言文字","en":"A language is a system of communication which consists of a set of sounds and written symbols which are used by the people of a particular country or region for talking or writing.","ex":{"en":"...the English language","cn":"英语"}},{"pos":"N-UNCOUNT 不可数名词","cn":"言语；语言表达","en":"Language is the use of a system of communication which consists of a set of sounds or written symbols.","ex":{"en":"Students examined how children acquire language","cn":"学生们仔细研究儿童如何习得语言。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"（某一领域的）全部词汇，术语","en":"You can refer to the words used in connection with a particular subject as the language of that subject.","ex":{"en":"...the language of business.","cn":"商业用语"}},{"pos":"N-UNCOUNT 不可数名词","cn":"粗话；脏话","en":"You can refer to someone's use of rude words or swearing as bad language when you find it offensive.","ex":{"en":"Television companies tend to censor bad language in feature films","cn":"电视公司往往会在审查故事片时删去其中的粗话。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"语言风格；措辞","en":"The language of a piece of writing or speech is the style in which it is written or spoken.","ex":{"en":"...a booklet summarising it in plain language","cn":"以平实语言对其作出概述的小册子"}},{"pos":"N-VAR 可变名词","cn":"交流方式，交际方式（包括可识别符号、非语言声音、动作等）","en":"You can use language to refer to various means of communication involving recognizable symbols, non-verbal sounds, or actions.","ex":{"en":"Some sign languages are very sophisticated means of communication.","cn":"有些手语可以表达非常复杂的内容。"}}]},"examples":[{"en":"Why study Latin? It's a dead language (= no longer spoken by anyone).","cn":"为什么学拉丁语？它已经不再有人说了。"},{"en":"It takes a long time to learn to speak a language well.","cn":"学会说好一种语言需要花很长的时间。"}]},"latent":{"media":{"uk":"media/uk/latent__gb_1.mp3","us":"media/us/latent__us_1.mp3"},"oxford":{"phon":"ˈleɪtnt","pos":"adjective","senses":[{"en":"existing, but not yet clear, active or well developed","cn":"潜在的；潜伏的；隐藏的","ex":{"en":"latent disease","cn":"隐匿性疾病"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"潜在的；潜藏的；隐伏的","en":"Latent is used to describe something which is hidden and not obvious at the moment, but which may develop further in the future.","ex":{"en":"Advertisements attempt to project a latent meaning behind an overt message.","cn":"广告的意图是以公开的信息传达隐含之意。"}}]},"examples":[{"en":"These children have a huge reserve of latent talent.","cn":"这些孩子蕴藏着极大的潜在天赋。"},{"en":"latent disease","cn":"潜伏性疾病"}]},"lawyer":{"oxford":{"phon":"ˈlɔɪə(r)","pos":"noun","senses":[{"en":"a person who is trained and qualified to advise people about the law and to represent them in court, and to write legal documents","cn":"律师","lab":"North American English","ex":{"en":"to hire a lawyer","cn":"聘请律师"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"律师","en":"A lawyer is a person who is qualified to advise people about the law and represent them in court.","ex":{"en":"Prosecution and defense lawyers are expected to deliver closing arguments next week.","cn":"下周控辩双方律师将进行结案陈词。"}}]},"media":{"uk":"media/uk/lawyer__gb_1.mp3","us":"media/us/lawyer__us_1.mp3"},"examples":[{"en":"Solicitor General","cn":"司法部副部长"},{"en":"district attorney","cn":"地方检察官"}]},"lava":{"oxford":{"phon":"ˈlɑːvə","pos":"noun","senses":[{"en":"hot liquid rock that comes out of a volcano","cn":"（火山喷出的）熔岩，岩浆","ex":{"en":"molten lava","cn":"熔化的火山岩浆"}},{"en":"this type of rock when it has cooled and become hard","cn":"火山岩"}]},"collins":{"senses":[{"pos":"N-MASS 物质名词","cn":"（火山）熔岩","en":"Lava is the very hot liquid rock that comes out of a volcano."}]},"media":{"uk":"media/uk/lava__gb_1.mp3","us":"media/us/lava__us_1.mp3"},"examples":[{"en":"molten lava","cn":"熔化的火山岩浆"}]},"labeled":{"lemma":"label"},"layers":{"lemma":"layer"},"laughter":{"media":{"uk":"media/uk/laughter__gb_1.mp3","us":"media/us/laughter__us_1.mp3"},"oxford":{"phon":"ˈlɑːftə(r)","pos":"noun","senses":[{"en":"the act or sound of laughing","cn":"笑；笑声","ex":{"en":"to roar/howl with laughter","cn":"放声／哈哈大笑"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"笑声","en":"Laughter is the sound of people laughing, for example because they are amused or happy.","ex":{"en":"Their laughter filled the corridor","cn":"整个走廊都回荡着他们的笑声。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"笑；快乐","en":"Laughter is the fact of laughing, or the feeling of fun and amusement that you have when you are laughing.","ex":{"en":"Pantomime is about bringing laughter to thousands","cn":"圣诞童话剧旨在把欢笑带给千千万万的人。"}}]},"examples":[{"en":"a house full of laughter (= with a happy atmosphere)","cn":"充满欢声笑语的房子"},{"en":"tears/gales/peals/shrieks of laughter","cn":"笑得流眼泪；阵阵笑声；哈哈大笑；阵阵尖声大笑"}]},"labels":{"lemma":"label"},"land-based":{"oxford":{"phon":"ˈlænd beɪst","pos":"adjective","senses":[{"en":"located on or living on the land","cn":"位于陆地上的；栖息于陆地的","ex":{"en":"land-based missiles","cn":"陆基导弹"}}]},"media":{"uk":"media/uk/land_based_1_gb_1.mp3","us":"media/us/land_based_1_us_1.mp3"},"examples":[{"en":"land-based missiles","cn":"陆基导弹"},{"en":"land-based animals","cn":"陆生动物"}]},"layer":{"oxford":{"phon":"ˈleɪə(r)","pos":"noun","senses":[{"en":"a quantity or sheet of something that lies over a surface or between surfaces","cn":"层；表层","ex":{"en":"A thin layer of dust covered everything.","cn":"所有的物品上都积了薄薄的一层灰尘。"}},{"en":"a level or part within a system or set of ideas","cn":"层次；阶层","ex":{"en":"There were too many layers of management in the company.","cn":"这家公司管理层级太多。"}},{"en":"to arrange something in layers","cn":"把…分层堆放","ex":{"en":"Layer the potatoes and onions in a dish.","cn":"把土豆和洋葱叠放在盘子里。"},"pos":"verb"},{"en":"to cut hair in layers of different lengths","cn":"分层剪发","ex":{"en":"Her hair had been layered.","cn":"她的头发被剪出层次。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"层","en":"A layer of a material or substance is a quantity or piece of it that covers a surface or that is between two other things.","ex":{"en":"A fresh layer of snow covered the street","cn":"街上覆盖了一层新雪。"}},{"pos":"N-COUNT 可数名词","cn":"层次；阶层；等级","en":"If something such as a system or an idea has many layers, it has many different levels or parts.","ex":{"en":"...an astounding ten layers of staff between the factory worker and the chief executive","cn":"工厂工人和首席执行官之间10个等级的巨大差距"}},{"pos":"VERB 动词","cn":"分层放置","en":"If you layer something, you arrange it in layers.","ex":{"en":"Layer the potatoes, asparagus and salmon in the tin","cn":"把土豆、芦笋和大麻哈鱼分层装入罐头内。"}}]},"media":{"uk":"media/uk/layer__gb_1.mp3","us":"media/us/layer__us_1.mp3"},"examples":[{"en":"A thin layer of dust covered everything.","cn":"所有的物品上都积了薄薄的一层灰尘。"},{"en":"Layer the potatoes and onions in a dish.","cn":"把土豆和洋葱叠放在盘子里。"}]},"lamb":{"oxford":{"phon":"læm","pos":"noun","senses":[{"en":"a young sheep","cn":"羔羊；小羊","g":"[countable]"},{"en":"meat from a young sheep","cn":"羊羔肉","g":"[uncountable]","ex":{"en":"a leg of lamb","cn":"羔羊腿肉"}},{"en":"used to describe or address somebody with love or sympathy","cn":"（亲昵或怜悯地描述或称呼某人）宝贝，乖乖","g":"[countable]","lab":"informal","ex":{"en":"You poor lamb!","cn":"可怜的宝贝！"}},{"en":"to give birth to a lamb","cn":"产羊羔","ex":{"en":"She’s due to lamb in two weeks’ time.","cn":"两周后她就要吃羊肉了。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"羔羊；羊羔；小羊","en":"A lamb is a young sheep.","ex":{"en":"Laura was basting the leg of lamb.","cn":"劳拉正往羔羊腿上浇抹油脂。"}},{"pos":"N-COUNT 可数名词","cn":"（对年幼者慈爱或怜悯的称呼）宝贝，乖乖","en":"People sometimes use lamb when they are addressing or referring to someone who they are fond of and who is young, gentle, or unfortunate.","ex":{"en":"She came and put her arms around me. 'You poor lamb. What's wrong?'","cn":"她走过来搂着我。“可怜的宝贝，出什么事儿啦？”"}},{"pos":"PHRASE 短语","cn":"温顺地；听话地；任人宰割地","en":"If you say that people do something like lambs or like lambs to the slaughter, you mean that they do what someone wants them to do without complaining or fighting.","ex":{"en":"The pair surrendered to him like lambs","cn":"那两个人乖乖地向他投降。"}},{"pos":"","cn":"","en":"mutton dressed as lamb→see: ;"}]},"media":{"uk":"media/uk/lamb__gb_1.mp3","us":"media/us/lamb__us_1.mp3","img":["media/ldoce/img/lamb.jpg"]},"examples":[{"en":"You poor lamb!","cn":"可怜的宝贝！"},{"en":"a leg of lamb","cn":"羔羊腿肉"}]},"lay":{"media":{"uk":"media/uk/lay__gb_1.mp3","us":"media/us/lay__us_1.mp3"},"oxford":{"phon":"leɪ","pos":"verb","senses":[{"en":"to put somebody/something in a particular position, especially when it is done gently or carefully","cn":"（尤指轻轻地或小心地）放置，安放，搁","g":"[transitive]","sc":"put down/spread","ex":{"en":"He laid a hand on my arm.","cn":"他把手搭在我的胳膊上。"}},{"en":"to spread something on something; to cover something with a layer of something","cn":"（在某物上）摊开，涂，敷；用一层…覆盖","g":"[transitive]","sc":"put down/spread","ex":{"en":"Before they started they laid newspaper on the floor.","cn":"他们开始前在地板上铺了报纸。"}},{"en":"to put something down, especially on the floor, ready to be used","cn":"铺，铺放，铺设（尤指在地板上）","g":"[transitive]","lab":"figurative","sc":"put down/spread","ex":{"en":"to lay a carpet/cable/pipe","cn":"铺地毯；铺设电缆；铺管道"}},{"en":"if a bird, an insect, a fish, etc. lays eggs, it produces them from its body","cn":"（鸟、昆虫、鱼等）下（蛋），产（卵）","g":"[transitive, intransitive]","sc":"eggs","ex":{"en":"The cuckoo lays its eggs in other birds' nests.","cn":"杜鹃在其他鸟的巢中下蛋。"}},{"en":"to arrange knives, forks, plates, etc. on a table ready for a meal","cn":"摆放餐具于（准备就餐）","g":"[transitive]","lab":"British English","sc":"table","ex":{"en":"to lay the table","cn":"摆好餐具准备用餐"}},{"en":"to present a proposal, some information, etc. to somebody for them to think about and decide on","cn":"提出，提交（建议、信息等）","g":"[transitive]","sc":"present proposal","ex":{"en":"The bill was laid before Parliament.","cn":"议案已提交议会审议。"}},{"en":"to put somebody/something in a particular position or state, especially a difficult or unpleasant one","cn":"使处于特定状态（尤指困境）","g":"[transitive]","lab":"formal","sc":"difficult situation","ex":{"en":"to lay a responsibility/burden on somebody","cn":"把责任／重担加于某人身上"}},{"en":"used with a noun to form a phrase that has the same meaning as the verb related to the noun","cn":"（与名词连用构成短语，其含义与该名词的相关动词相同）","g":"[transitive]","sc":"with nouns","ex":{"en":"to lay the blame on somebody (= to blame somebody)","cn":"归咎于某人"}},{"en":"to prepare something in detail","cn":"周密准备；筹划；设置","g":"[transitive]","sc":"plan/trap","ex":{"en":"Little did he know they had laid a trap for him.","cn":"他根本不知道他们为他设下了陷阱。"}},{"en":"to have sex with somebody","cn":"与（某人）性交","g":"[transitive, usually passive]","lab":"slang","sc":"have sex","ex":{"en":"He went out hoping to get laid that night.","cn":"他那天晚上外出，希望找个女人睡一宿。"}},{"en":"to prepare a fire by arranging wood, sticks or coal","cn":"（摆好木、柴或煤）生火","g":"[transitive]","sc":"fire"},{"en":"to bet money on something; to place a bet","cn":"对…下赌金；下赌注","g":"[transitive]","sc":"bet","ex":{"en":"to lay a bet","cn":"下赌注"}},{"en":"not having expert knowledge or professional qualifications in a particular subject","cn":"外行的；非专业的；缺少专门知识的","ex":{"en":"His book explains the theory for the lay public.","cn":"他的书为普通大众阐明了这个理论。"},"pos":"adjective"},{"en":"not in an official position in the Church","cn":"平信徒的；在俗的","ex":{"en":"a lay preacher","cn":"在俗传道员"},"pos":"adjective"},{"en":"a partner in sex","cn":"性交对象","lab":"slang, offensive，，","ex":{"en":"to be a great lay","cn":"为荒淫无度的荡妇"},"pos":"noun"},{"en":"a poem that was written to be sung, usually telling a story","cn":"（供吟唱的）叙事诗","lab":"old use","pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"放置；安放；搁","en":"If you lay something somewhere, you put it there in a careful, gentle, or neat way.","ex":{"en":"Lay a sheet of newspaper on the floor","cn":"在地上铺一张报纸。"}},{"pos":"VERB 动词","cn":"布置（餐桌）；摆放（餐具）","en":"If you lay the table or lay the places at a table, you arrange the knives, forks, and other things that people need on the table before a meal.","ex":{"en":"The butler always laid the table.","cn":"每次都是男管家把餐具摆好。"}},{"pos":"VERB 动词","cn":"铺放；敷设；铺设","en":"If you lay something such as carpets, cables, or foundations, you put them into their permanent position.","ex":{"en":"A man came to lay the saloon carpet","cn":"一名男子来铺客厅的地毯。"}},{"pos":"VERB 动词","cn":"布设，设置（陷阱）","en":"To lay a trap means to prepare it in order to catch someone or something.","ex":{"en":"They were laying a trap for the kidnapper.","cn":"他们设下一个圈套引绑匪上钩。"}},{"pos":"VERB 动词","cn":"（鸟）产（卵），下（蛋）","en":"When a female bird lays an egg, it produces an egg by pushing it out of its body.","ex":{"en":"My canary has laid an egg","cn":"我的金丝雀生了一个蛋。"}},{"pos":"VERB 动词","cn":"奠定基础/制定规划","en":"Lay is used with some nouns to talk about making official preparations for something. For example, if you lay the basis for something or lay plans for it, you prepare it carefully.","ex":{"en":"Diplomats meeting in Chile have laid the groundwork for far-reaching environmental regulations","cn":"在智利会面的外交官们已经为那些对未来影响深远的环境保护条例的制定打好了基础。"}},{"pos":"VERB 动词","cn":"归咎/起诉","en":"Lay is used with some nouns in expressions about accusing or blaming someone. For example, if you lay the blame for a mistake on someone, you say it is their fault, or if the police lay charges against someone, they officially accuse that person of a crime.","ex":{"en":"She refused to lay the blame on any one party","cn":"她拒绝归咎于任何一方。"}},{"pos":"VERB 动词","cn":"押（赌注）；就…打赌","en":"If you say that you would lay bets, odds, or money on something happening, you mean that you are very confident that it will happen.","ex":{"en":"I wouldn't lay bets on his still remaining manager after the spring","cn":"我看他的这个经理当不到春天之后了。"}},{"pos":"VERB 动词","cn":"（指交媾）干，搞","en":"To lay someone means to have sex with them."},{"pos":"N-COUNT 可数名词","cn":"床上功夫高者/轻易就上床者","en":"Lay is used in expressions such a good lay or an easy lay to describe what someone is like as a sexual partner."},{"pos":"PHRASE 短语","cn":"过分夸大；言过其实","en":"If someone is laying it on thick or is laying it on, they are exaggerating a statement, experience, or emotion in order to try to impress people.","ex":{"en":"Don't lay it on too thick, but make sure they are flattered","cn":"不要吹捧得太露骨，不过一定要恭维得他们很惬意。"}},{"pos":"PHRASE 短语","cn":"使易受批评（或攻击）","en":"If you lay yourself open to criticism or attack, or if something lays you open to it, something you do makes it possible or likely that other people will criticize or attack you.","ex":{"en":"The party thereby lays itself open to charges of conflict of interest","cn":"该党因此难免被人指责有利益冲突。"}},{"pos":"","cn":"","en":"to lay something bare→see: ; to lay claim to something→see: ; to lay something at someone's door→see: ; to lay eyes on something→see: ; to lay a finger on someone→see: ; to lay your hands on something→see: ; to lay down the law→see: ; to lay down your life→see: ; to lay something to rest→see: ; to lay siege to something→see: ; to lay waste→see: ;"},{"pos":"","cn":"","en":"相关词组：lay aside lay before lay down lay in lay into lay off lay on lay out lay up"},{"pos":"ADJ 形容词","cn":"（基督教中）平信徒的，世俗的，非神职的","en":"You use lay to describe people who are involved with a Christian church but are not members of the clergy or are not monks or nuns.","ex":{"en":"Edwards is a Methodist lay preacher and social worker.","cn":"爱德华是一位循道宗在俗传教士兼社会工作者。"}},{"pos":"ADJ 形容词","cn":"业余的；外行的；门外汉的","en":"You use lay to describe people who are not experts or professionals in a particular subject or activity.","ex":{"en":"It is difficult for a lay person to gain access to medical libraries","cn":"非业内人士难以进入医学图书馆。"}}]},"examples":[{"en":"It is laid down that all candidates must submit three copies of their dissertation.","cn":"根据规定，所有学位答辩人均须提交论文一式三份。"},{"en":"If you eat too much, the surplus is laid down as fat.","cn":"要是吃得太多，过剩的营养就会积聚成为脂肪。"}]},"lam":{"oxford":{"phon":"læm","pos":"noun","senses":[{"en":"( NAmE ) ( informal ) escaping from sb, especially from the police","cn":"在逃，逃匿（尤指逃避警方追缉）"},{"en":"( BrE ) ( informal ) to attack sb violently with blows or words","cn":"痛打某人；猛烈抨击某人"}]},"collins":{"senses":[{"pos":"","cn":"（为逃避警方或敌人追捕）在逃，逃匿","en":"If someone is on the lam or if they go on the lam, they are trying to escape or hide from someone such as the police or an enemy.","ex":{"en":"He was on the lam for seven years.","cn":"他已在逃7年。"}}]},"media":{"uk":"media/uk/lam__gb_1.mp3","us":"media/us/lam__us_1.mp3"},"examples":[{"en":"She really lammed into her opponent during the debate.","cn":"在辩论中她着实给对手以猛烈的攻击。"},{"en":"Brenner was recaptured after three weeks on the lam.","cn":"布伦纳潜逃三个星期后被再次抓获。"}]},"laboured":{"media":{"uk":"media/uk/laboured__gb_1.mp3","us":"media/us/laboured__us_1.mp3"},"oxford":{"phon":"ˈleɪbəd","pos":"adjective","senses":[{"en":"slow and taking a lot of effort","cn":"缓慢而困难的","ex":{"en":"Her breathing became more and more laboured.","cn":"她的呼吸变得越来越困难。"}},{"en":"not natural and seeming to take a lot of effort","cn":"不自然的；费力的；矫揉造作的","ex":{"en":"The movie looks laboured and slow by today’s standards.","cn":"以今天的标准来看，这部电影看起来既费力又缓慢。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（呼吸）缓慢的，困难的，费力的","en":"If someone's breathing is laboured, it is slow and seems to take a lot of effort.","ex":{"en":"From his slow walk and laboured breathing, Ginny realized he was far from well.","cn":"看他步履缓慢、呼吸困难的样子，金尼意识到他的身体还远未恢复。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（文章或言谈）刻意的，矫揉造作的","en":"If something such as someone's writing or speech is laboured, they have put too much effort into it so it seems awkward and unnatural.","ex":{"en":"The prose of his official communications was so laboured, pompous and verbose","cn":"他笔下的公文矫揉浮华，长篇大论。"}}]},"examples":[{"en":"Some of the episodes are very laboured.","cn":"有几集剧情很牵强。"}],"base":"labour"},"layout":{"media":{"uk":"media/uk/layout__gb_1.mp3","us":"media/us/layout__us_1.mp3"},"oxford":{"phon":"ˈleɪaʊt","pos":"noun","senses":[{"en":"the way in which the parts of something such as the page of a book, a website, a garden or a building are arranged","cn":"布局；布置；设计","ex":{"en":"the layout of streets","cn":"街道的布局"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"布置；设计；布局","en":"The layout of a garden, building, or piece of writing is the way in which the parts of it are arranged.","ex":{"en":"He tried to recall the layout of the farmhouse","cn":"他努力回想农舍的布局。"}}]},"examples":[{"en":"the magazine's attractive new page layout","cn":"杂志漂亮的新版面设计"},{"en":"the layout of streets","cn":"街道的布局"}]},"label":{"oxford":{"phon":"ˈleɪbl","pos":"noun","senses":[{"en":"a piece of paper, etc. that is attached to something and that gives information about it","cn":"标签；签条；标记","ex":{"en":"Always read the label carefully.","cn":"务必仔细阅读标签。"}},{"en":"a word or phrase that is used to describe somebody/something in a way that seems too general, unfair or not correct","cn":"（不恰当的）称谓，绰号，叫法","lab":"disapproving","ex":{"en":"I hated the label ‘housewife’.","cn":"我不喜欢“家庭主妇”这个称谓。"}},{"en":"the name or trademark of a fashion company","cn":"品牌标签","ex":{"en":"today's major fashion labels","cn":"当今各大时尚品牌"}},{"en":"a company that produces and sells music, CDs, etc.","cn":"唱片公司","ex":{"en":"the Virgin record label","cn":"维京唱片公司"}},{"en":"to fix a label on something or write information on something","cn":"贴标签于；用标签标明","ex":{"en":"Make sure that your luggage is clearly labelled.","cn":"确保您的行李有清晰的标签。"},"pos":"verb"},{"en":"to describe somebody/something in a particular way, especially unfairly","cn":"（尤指不公正地）把…称为","ex":{"en":"He was labelled (as) a traitor by his former colleagues.","cn":"他被以前的同事称为叛徒。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"标签；签条；标贴","en":"A label is a piece of paper or plastic that is attached to an object in order to give information about it.","ex":{"en":"He peered at the label on the bottle.","cn":"他仔细地看着瓶上的标签。"}},{"pos":"VERB 动词","cn":"贴标签于；用标签标明","en":"If something is labelled, a label is attached to it giving information about it.","ex":{"en":"The stuff has never been properly logged and labelled","cn":"这些东西从未进行过妥善登记，也没有贴标签标注。"}},{"pos":"VERB 动词","cn":"（不公平地）把…称为，把…列为","en":"If you say that someone or something is labelled as a particular thing, you mean that people generally describe them that way and you think that this is unfair.","ex":{"en":"Too often the press are labelled as bad boys","cn":"记者们往往被视为捣蛋分子。"}},{"pos":"N-COUNT 可数名词","cn":"（批评性的）标签，称号","en":"If you say that someone gets a particular label, you mean that people show disapproval of them by describing them with a critical word or phrase.","ex":{"en":"Her treatment of her husband earned her the label of the most hated woman in America.","cn":"她对待丈夫的行径使她赢得了“全美最可恶的女人”的称号。"}},{"pos":"N-COUNT 可数名词","cn":"唱片公司","en":"You can refer to a company that produces and sells CDs as a particular label .","ex":{"en":"She landed a contract with record label EMI","cn":"她获得了一份与百代唱片公司的合约。"}}]},"media":{"img":["media/pic/label_comp.jpg","media/thumb/label.jpg"],"uk":"media/uk/label__gb_1.mp3","us":"media/us/label__us_1.mp3"},"examples":[{"en":"We tested various supermarkets' own label pasta sauces (= those marked with the name of the shop/store where they are sold).","cn":"我们检查了各大超市的自家商标意大利面调味汁。"},{"en":"We carefully labelled each item with the contents and the date.","cn":"我们仔细地把每件物品用标签标明成分和日期。"}]},"laughing":{"media":{"uk":"media/uk/laughing__gb_1.mp3","us":"media/us/laughing__us_1.mp3"},"oxford":{"phon":"ˈlɑːfɪŋ","pos":"adjective","senses":[{"en":"showing that you think something is funny; showing happiness","cn":"带笑意的；笑盈盈的","ex":{"en":"his laughing blue eyes","cn":"他笑盈盈的蓝眼睛"}}]},"examples":[{"en":"his laughing blue eyes","cn":"他带着笑意的蓝眼睛"},{"en":"laughing faces","cn":"笑脸"}],"base":"laugh"},"lake":{"media":{"uk":"media/uk/lake__gb_1.mp3","us":"media/us/lake__us_1.mp3"},"oxford":{"phon":"leɪk","pos":"noun","senses":[{"en":"a large area of water that is surrounded by land","cn":"湖；湖泊","lab":"figurative","ex":{"en":"We swam in the lake.","cn":"我们在湖里游泳。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"湖；湖泊","en":"A lake is a large area of fresh water, surrounded by land.","ex":{"en":"They can go fishing in the lake","cn":"他们可以在湖里钓鱼。"}}]},"examples":[{"en":"We swam in the lake.","cn":"我们在湖里游泳。"},{"en":"( figurative ) a wine lake (= a large supply of wine that is not being used)","cn":"葡萄酒池"}]},"labs":{"lemma":"lab","media":{"uk":"media/uk/lab__gb_1.mp3","us":"media/us/lab__us_1.mp3"}},"lateral":{"oxford":{"phon":"ˈlætərəl","pos":"adjective","senses":[{"en":"relating to the side of something or to movement to the side","cn":"侧面的；横向的；向侧面移动的","ex":{"en":"the lateral branches of a tree","cn":"树的侧枝"}},{"en":"a side part of something, especially a shoot or branch that grows out from the side of a plant or tree","cn":"侧向生长的东西（尤指嫩芽或树枝）","lab":"specialist","ex":{"en":"In winter, prune back laterals.","cn":"冬季，修剪后侧枝。"},"pos":"noun"},{"en":"a pass thrown back or to the side","cn":"向后传球；横向传球；侧向传球","ex":{"en":"Pryor threw a lateral to Palmer.","cn":"普赖尔把球侧传给帕尔默。"},"pos":"noun"},{"en":"a consonant sound that is produced by placing a part of the tongue against the palate so that air flows around it on both sides, for example /l/ in lie","cn":"边音（如 lie 一词中 /l/ 的发音）","lab":"phonetics","pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"侧面的；横向的；侧向的","en":"Lateral means relating to the sides of something, or moving in a sideways direction.","ex":{"en":"McKinnon estimated the lateral movement of the bridge to be between four and six inches.","cn":"麦金农估计大桥的侧向移动介于4至6英寸之间。"}}]},"media":{"uk":"media/uk/lateral__gb_1.mp3","us":"media/us/lateral__us_1.mp3"},"examples":[{"en":"the lateral branches of a tree","cn":"树的侧枝"},{"en":"lateral eye movements","cn":"眼睛的两侧运动"}]},"land":{"media":{"uk":"media/uk/land__gb_1.mp3","us":"media/us/land__us_1.mp3"},"oxford":{"phon":"lænd","pos":"noun","senses":[{"en":"the surface of the earth that is not sea","cn":"陆地；大地","g":"[uncountable]","lab":"especially North American English","sc":"surface of earth","ex":{"en":"The new project will reclaim the land from the sea.","cn":"新项目将填海造地。"}},{"en":"an area of ground, especially of a particular type or used for a particular purpose","cn":"（尤指某类型或作某种用途的）地带，土地","g":"[uncountable]","lab":"North American English","sc":"area of ground","ex":{"en":"agricultural/arable/fertile land","cn":"农业用地；可耕地；肥沃的土地"}},{"en":"the area of ground that somebody owns, especially when you think of it as property that can be bought or sold","cn":"地产；地皮","g":"[uncountable]","lab":"formal","sc":"area of ground","ex":{"en":"public/private land","cn":"公共／私人土地"}},{"en":"used to refer to the countryside and the way people live in the country as opposed to in cities","cn":"（与城市相对的）农村，农村生活方式","g":"[uncountable]","sc":"countryside","ex":{"en":"At the beginning of the 20th century almost a third of the population lived off the land (= grew or produced their own food).","cn":"20 世纪初几乎有三分之一的人口依靠种地为生。"}},{"en":"used to refer to a country or region in a way that involves the emotions or the imagination","cn":"（涉及感情或想象的）国家，地区","g":"[countable]","lab":"literary","sc":"country/region","ex":{"en":"She longed to return to her native land.","cn":"她渴望回到她的祖国。"}},{"en":"to come down through the air onto the ground or another surface","cn":"落；降落；着陆","g":"[intransitive]","sc":"of bird/plane/insect","ex":{"en":"The plane landed safely.","cn":"飞机安全着陆了。"},"pos":"verb"},{"en":"to control a plane and bring it down to the ground","cn":"使（飞机）着陆","g":"[transitive]","sc":"of pilot","ex":{"en":"The pilot landed the plane safely.","cn":"飞行员驾驶飞机安全着陆。"},"pos":"verb"},{"en":"to arrive somewhere in a plane or a boat","cn":"（乘飞机或船）着陆，登陆","g":"[intransitive]","sc":"arrive in plane/boat","ex":{"en":"The flight is due to land at 3 o'clock.","cn":"航班预定在 3 点钟着陆。"},"pos":"verb"},{"en":"to put somebody/something on land from an aircraft, a boat, etc.","cn":"（使）着陆，降落，靠岸，登陆","g":"[transitive]","sc":"arrive in plane/boat","ex":{"en":"The troops were landed by helicopter.","cn":"部队乘直升机降落。"},"pos":"verb"},{"en":"to come down somewhere after jumping, falling or being thrown","cn":"跳落，跌落，被抛落（地面）","g":"[intransitive]","sc":"fall to ground","ex":{"en":"She fell and landed heavily on her back.","cn":"她重重地仰面摔倒在地。"},"pos":"verb"},{"en":"to arrive somewhere and cause difficulties that have to be dealt with","cn":"降临；使陷于（困境）；使不得不应付","g":"[intransitive]","sc":"difficulties","ex":{"en":"Why do complaints always land on my desk (= why do I always have to deal with them)?","cn":"为什么投诉总得要我来处理？"},"pos":"verb"},{"en":"to succeed in getting a job, etc., especially one that a lot of other people want","cn":"成功得到，赢得，捞到（尤指许多人想得到的工作）","g":"[transitive]","lab":"informal","sc":"job","ex":{"en":"He's just landed a starring role in a Hollywood movie.","cn":"他刚刚得到主演一部好莱坞电影的机会。"},"pos":"verb"},{"en":"to catch a fish and bring it out of the water on to the land","cn":"捕到，钓到（鱼）","g":"[transitive]","sc":"fish","ex":{"en":"It took me three attempts to land the fish.","cn":"我尝试了三次才把鱼上岸。"},"pos":"verb"},{"en":"to score a penalty (4) or conversion (3)","cn":"土地：罚分（4）或转换（3）","g":"[transitive]","sc":"rugby","ex":{"en":"Ceri Sweeney landed a penalty with the last kick of the half.","cn":"切里·斯威尼在上半场最后一脚主罚点球。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"土地；田地；（尤指）耕作用地，建筑用地","en":"Land is an area of ground, especially one that is used for a particular purpose such as farming or building.","ex":{"en":"Good agricultural land is in short supply.","cn":"良田短缺。"}},{"pos":"N-COUNT 可数名词","cn":"（属于某人的）地产，地皮","en":"You can refer to an area of land which someone owns as their land or their lands.","ex":{"en":"Their home is on his father's land","cn":"他们的家建在他父亲拥有的地皮上。"}},{"pos":"N-SING 单数名词","cn":"农耕；农村生活","en":"If you talk about the land, you mean farming and the way of life in farming areas, in contrast to life in the cities.","ex":{"en":"Living off the land was hard enough at the best of times.","cn":"即使在年景最好的时候，务农为生也是相当艰辛的。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"陆地；大地","en":"Land is the part of the world that consists of ground, rather than sea or air.","ex":{"en":"It isn't clear whether the plane went down over land or sea.","cn":"不清楚飞机是坠毁在陆地上还是海里。"}},{"pos":"N-COUNT 可数名词","cn":"国度；国土","en":"You can use land to refer to a country in a poetic or emotional way. →see usage note at:","ex":{"en":"Her husband's body lies buried 2,000 miles away in a strange land.","cn":"她丈夫的遗体埋葬在两千英里外一个陌生的国度。"}},{"pos":"VERB 动词","cn":"落下；跌落","en":"When someone or something lands, they come down to the ground after moving through the air or falling.","ex":{"en":"He was sent flying into the air and landed 20ft away","cn":"他被抛到空中，落在20英尺外的地方。"}},{"pos":"V-ERG 及物/不及物动词","cn":"（使）着陆；（使）登陆；抵达","en":"When someone lands a plane, ship, or spacecraft, or when it lands, it arrives somewhere after a journey.","ex":{"en":"The jet landed after a flight of just under three hours","cn":"这架喷气式飞机在飞行了将近3小时后降落了。"}},{"pos":"VERB 动词","cn":"（尤指船只）卸（货）","en":"To land goods somewhere means to unload them there at the end of a journey, especially by ship.","ex":{"en":"The vessels will have to land their catch at designated ports.","cn":"船只必须在指定的港口把捕到的鱼卸下。"}},{"pos":"V-ERG 及物/不及物动词","cn":"（使）落入；（使）陷于","en":"If you land in an unpleasant situation or place or if something lands you in it, something causes you to be in it.","ex":{"en":"He landed in a psychiatric ward","cn":"他被关进了精神病房。"}},{"pos":"VERB 动词","cn":"使遭遇（困境）","en":"If someone or something lands you with a difficult situation, they cause you to have to deal with the difficulties involved.","ex":{"en":"The other options simply complicate the situation and could land him with more expense.","cn":"其他办法只会使情况复杂化，而且可能给他带来更大花销。"}},{"pos":"VERB 动词","cn":"意外到来；突然冒出","en":"If something lands somewhere, it arrives there unexpectedly, often causing problems.","ex":{"en":"Two days later the book had already landed on his desk","cn":"两天后那本书竟然已经摆在了他的书桌上。"}},{"pos":"VERB 动词","cn":"抓到，钓到（鱼）","en":"If you land a fish, you succeed in catching it and getting it out of the water.","ex":{"en":"One angler landed fish of 10 lb and 9 lb on the same day.","cn":"一名垂钓者在同一天分别钓到了10磅和9磅重的鱼。"}},{"pos":"VERB 动词","cn":"搞到；弄到；捞到","en":"If you land something that is difficult to get and that many people want, you are successful in getting it.","ex":{"en":"He landed a place on the graduate training scheme","cn":"他在毕业生培训计划中赢得了一个位置。"}},{"pos":"V-ERG 及物/不及物动词","cn":"击；打","en":"If someone lands a blow or punch or if their blow or punch lands, they hit someone.","ex":{"en":"De Leon landed a punch on the Italian's mouth after the end of the eleventh round","cn":"11个回合过后，德莱昂一拳击在那个意大利人的嘴巴上。"}},{"pos":"","cn":"","en":"to land on your feet→see: ;"},{"pos":"","cn":"","en":"相关词组：land up"}]},"examples":[{"en":"He's just landed a starring role in Spielberg's next movie.","cn":"他刚得到一个机会，在斯皮尔伯格执导的下一部电影里担任主角。"},{"en":"Pete and Jo were still in the land of Nod, so I went out for a walk in the morning sunshine.","cn":"皮特和乔仍沉睡未醒，于是我就在晨光中出门散步去了。"}]},"lasts":{"lemma":"last","media":{"uk":"media/uk/last__gb_1.mp3","us":"media/us/last__us_1.mp3"}},"lax":{"media":{"uk":"media/uk/lax__gb_1.mp3","us":"media/us/lax__us_1.mp3"},"oxford":{"phon":"læks","pos":"adjective","senses":[{"en":"not strict, severe or careful enough about work, rules or standards of behaviour","cn":"不严格的；不严厉的；马虎的","lab":"disapproving","ex":{"en":"lax security/discipline","cn":"不严格的保安措施／纪律"}},{"en":"relaxed","cn":"松弛的","ex":{"en":"Her body went completely lax in his arms.","cn":"她的身体在他怀里彻底松弛下来。"}},{"en":"produced with the muscles of the speech organs relaxed","cn":"松弛的；松音的","lab":"phonetics"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"松懈的；马虎的；不严格的","en":"If you say that a person's behaviour or a system is lax, you mean they are not careful or strict about maintaining high standards.","ex":{"en":"One of the problem areas is lax security for airport personnel","cn":"问题之一是对机场员工的安检措施马虎松懈。"}}]},"examples":[{"en":"a lax attitude to health and safety regulations","cn":"对卫生与安全条例的马虎态度"},{"en":"lax security/discipline","cn":"不严格的保安措施/纪律"}]},"lawyers":{"lemma":"lawyer"},"labor":{"collins":{"senses":[{"pos":"","cn":"","en":"→see: ;"}]},"media":{"uk":"media/uk/labor__gb_1.mp3","us":"media/us/labor__us_1.mp3"},"oxford":{"phon":"","pos":"noun","senses":[{"en":"work, especially physical work","cn":"劳动；（尤指）体力劳动","g":"[uncountable]","ex":{"en":"manual labor (= work using your hands)","cn":"身体劳动"}},{"en":"a task or period of work","cn":"任务；（一段时间的）工作","g":"[countable, usually plural]","lab":"formal","ex":{"en":"He was so exhausted from the day's labors that he went straight to bed.","cn":"一天的工作让他筋疲力尽，直接上床睡觉了。"}},{"en":"the people who work or are available for work in a country or company","cn":"（统称）劳工，工人；劳动力","g":"[uncountable]","ex":{"en":"child/forced/slave labor","cn":"童工/强迫/奴役劳动"}},{"en":"the period of time or the process of giving birth to a baby","cn":"分娩期；分娩；生产","g":"[uncountable, countable, usually singular]","ex":{"en":"Jane was in labor for ten hours.","cn":"简分娩了十个小时。"}},{"en":"to try very hard to do something difficult","cn":"努力做（困难的事）","g":"[intransitive]","sc":"struggle","ex":{"en":"He was in his study laboring away over some old papers.","cn":"他正在书房里埋头苦读一些旧论文。"},"pos":"verb"},{"en":"to do hard physical work","cn":"干苦力活","g":"[intransitive]","lab":"old-fashioned","sc":"work hard","ex":{"en":"We labored all day in the fields.","cn":"我们整天在田里劳作。"},"pos":"verb"},{"en":"to move with difficulty and effort","cn":"困难吃力地行进","g":"[intransitive]","sc":"move with difficulty","ex":{"en":"The horses labored up the steep slope.","cn":"马匹费力地爬上陡峭的斜坡。"},"pos":"verb"}]}},"large-scale":{"oxford":{"phon":"ˌlɑːdʒ ˈskeɪl","pos":"adjective","senses":[{"en":"involving many people or things, especially over a wide area","cn":"大规模的；大批的；大范围的","ex":{"en":"Large areas of the forest will be cleared for ranching as part of a large-scale development plan.","cn":"作为大规模的开发计划的一部分，大片森林将被清除改成牧场。"}},{"en":"drawn or made to a scale that shows a small area of land or a building in great detail","cn":"按大比例绘制（或制作）的；大比例尺的"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"大规模的；大范围的；大型的","en":"A large-scale action or event happens over a very wide area or involves a lot of people or things.","ex":{"en":"...a large scale military operation.","cn":"大规模的军事行动"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（地图或图表）大比例尺的","en":"A large-scale map or diagram represents a small area of land or a building or machine on a scale that is large enough for small details to be shown.","ex":{"en":"...a large-scale map of the county.","cn":"一张大比例尺的郡地图"}}]},"media":{"uk":"media/uk/large_scale_1_gb_1.mp3","us":"media/us/large_scale_1_us_1.mp3"},"examples":[{"en":"the large-scale employment of women","cn":"对女性大批的雇用"},{"en":"large-scale development","cn":"大规模的开发"}]},"lazy":{"media":{"uk":"media/uk/lazy__gb_1.mp3","us":"media/us/lazy__us_1.mp3"},"oxford":{"phon":"ˈleɪzi","pos":"adjective","senses":[{"en":"unwilling to work or be active; doing as little as possible","cn":"不愿工作的；懒散的；懒惰的","lab":"disapproving","ex":{"en":"He was not stupid, just lazy.","cn":"他不笨，只是懒。"}},{"en":"not involving much energy or activity; slow and relaxed","cn":"无精打采的；懒洋洋的","ex":{"en":"We spent a lazy day on the beach.","cn":"我们在海滩上懒洋洋地度过了一天。"}},{"en":"showing a lack of effort or care","cn":"没下功夫的；粗枝大叶的；马虎的","lab":"disapproving","ex":{"en":"a lazy piece of work","cn":"粗制滥造的作品"}},{"en":"moving slowly","cn":"行进缓慢的；慢吞吞的","lab":"literary","ex":{"en":"the lazy river","cn":"缓缓流淌的河水"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"懒惰的；懒散的","en":"If someone is lazy, they do not want to work or make any effort to do anything.","ex":{"en":"Lazy and incompetent police officers are letting the public down","cn":"懒惰兼无能的警官令公众失望。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"令人精神松弛的；令人懒洋洋的","en":"You can use lazy to describe an activity or event in which you are very relaxed and which you do or take part in without making much effort.","ex":{"en":"Her latest novel is perfect for a lazy summer's afternoon reading","cn":"在慵懒的夏日午后阅读她的最新小说最合适不过了。"}},{"pos":"ADJ 形容词","cn":"徐徐的；缓缓的","en":"If you describe something as lazy, you mean that it moves or flows slowly and gently.","ex":{"en":"...a valley of rolling farms spread out along a lazy river.","cn":"山谷里的农田起伏绵延，旁边一条溪水缓缓而过"}}]},"examples":[{"en":"We spent a lazy day on the beach.","cn":"我们在海滩上懒洋洋地度过了一天。"},{"en":"I was feeling too lazy to go out.","cn":"我当时懒得动，不愿意外出。"}]},"lab":{"media":{"uk":"media/uk/lab__gb_1.mp3","us":"media/us/lab__us_1.mp3"},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"同laboratory","en":"A lab is the same as a laboratory ."},{"pos":"","cn":"（英国）工党","en":"In Britain, Lab is the written abbreviation for (书面缩略=) Labour.","ex":{"en":"...David Blunkett, MP for Sheffield (Lab).","cn":"代表谢菲尔德的下院议员戴维·布伦基特（工党）"}}]},"examples":[{"en":"a lab coat (= a white coat worn by scientists, etc. working in a laboratory)","cn":"实验室白袍"},{"en":"a lab technician","cn":"实验室技术员"}],"oxford":{"phon":"læb","pos":"noun","senses":[{"en":"a laboratory","cn":"实验室","ex":{"en":"a computer/research lab","cn":"计算机／研究实验室"}},{"en":"Labour","cn":"工党","pos":"abbreviation"}]}},"laid":{"lemma":"lay","media":{"uk":"media/uk/laid__gb_1.mp3","us":"media/us/laid__us_1.mp3"}},"late":{"media":{"uk":"media/uk/late__gb_1.mp3","us":"media/us/late__us_1.mp3"},"oxford":{"phon":"leɪt","pos":"adjective","senses":[{"en":"arriving, happening or done after the expected, arranged or usual time","cn":"迟到；迟发生；迟做","g":"[not usually before noun]","ex":{"en":"I'm sorry I'm late.","cn":"对不起，我迟到了。"}},{"en":"near the end of a period of time, a person’s life, etc.","cn":"接近末期的；晚年的","g":"[only before noun]","ex":{"en":"in the late afternoon","cn":"傍晚"}},{"en":"near the end of the day","cn":"近日暮的；近深夜的","ex":{"en":"Let's go home—it's getting late.","cn":"咱们回家吧，时间不早了。"}},{"en":"no longer alive","cn":"已故的","g":"[only before noun]","lab":"formal","ex":{"en":"She spoke of her late husband with passion.","cn":"她说到已故的丈夫时语气里充满了爱意。"}},{"en":"after the expected, arranged or usual time","cn":"迟；晚","ex":{"en":"I got up late.","cn":"我起晚了。"},"pos":"adverb"},{"en":"near the end of a period of time, a person’s life, etc.","cn":"接近末期的；晚年的","ex":{"en":"It happened late last year.","cn":"那事发生在去年年底。"},"pos":"adverb"},{"en":"near the end of the day","cn":"近日暮的；近深夜的","ex":{"en":"There's a good film on late.","cn":"深夜有一场好电影。"},"pos":"adverb"}]},"collins":{"senses":[{"pos":"ADV-GRADED 副词","cn":"（时间上）接近终了，临近末了","en":"Late means near the end of a day, week, year, or other period of time.","ex":{"en":"It was late in the afternoon","cn":"那是下午近黄昏的时候。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"近日暮的；近深夜的；时间不早的","en":"If it is late, it is near the end of the day or it is past the time that you feel something should have been done.","ex":{"en":"It was very late and the streets were deserted","cn":"时间已很晚，街上空空荡荡。"}},{"pos":"ADV-GRADED 副词","cn":"（比安排或预计时间）晚，迟","en":"Late means after the time that was arranged or expected.","ex":{"en":"Steve arrived late","cn":"史蒂夫迟到了。"}},{"pos":"ADV-GRADED 副词","cn":"（比通常时间）晚，迟","en":"Late means after the usual time that a particular event or activity happens.","ex":{"en":"We went to bed very late","cn":"我们很晚才睡。"}},{"pos":"ADJ 形容词","cn":"已故的；已逝的；（尤指）新近去世的","en":"You use late when you are talking about someone who is dead, especially someone who has died recently.","ex":{"en":"...my late husband.","cn":"我已故的丈夫"}},{"pos":"ADJ 形容词","cn":"在…居住（或工作）直至最近的","en":"Someone who is late of a particular place or institution lived or worked there until recently.","ex":{"en":"...Cousin Zachary, late of Bellevue Avenue.","cn":"直到不久前还住在贝尔邬大道的表兄扎卡里"}},{"pos":"CONVENTION 惯用语","cn":"迟到好过没到；晚做好过不做","en":"If you say better late than never when someone has done something, you think they should have done it earlier.","ex":{"en":"It's been a long time coming but better late than never.","cn":"早就该如此了。不过，也总比没有的强。"}},{"pos":"PHRASE 短语","cn":"为时已晚；坐失良机","en":"If you say that someone is doing something late in the day, you mean that their action or behaviour may not be fully effective because they have waited too long before doing it.","ex":{"en":"I'd left it all too late in the day to get anywhere with these strategies.","cn":"我按兵不动时间太长，致使这些策略都不管用了。"}},{"pos":"PHRASE 短语","cn":"新近；最近；近来","en":"You use of late to refer to an event or state of affairs that happened or began to exist a short time ago.","ex":{"en":"His life has changed of late","cn":"他的生活近来发生了变化。"}},{"pos":"PHRASE 短语","cn":"为时已晚；过迟","en":"If an action or event is too late, it is useless or ineffective because it occurs after the best time for it.","ex":{"en":"It was too late to turn back","cn":"回头已经太晚了。"}},{"pos":"","cn":"","en":"a late night→see: ;"}]},"examples":[{"en":"As late as (= as recently as) the 1950s, tuberculosis was still a fatal illness.","cn":"直到 20 世纪 50 年代，结核病仍然是一种致命的疾病。"},{"en":"The school was built in the late 1970s.","cn":"这所学校建于 20 世纪 70 年代末。"}]},"large":{"media":{"uk":"media/uk/large__gb_1.mp3","us":"media/us/large__us_1.mp3"},"oxford":{"phon":"lɑːdʒ","pos":"adjective","senses":[{"en":"big in size or quantity","cn":"大的；大规模的；大量的","ex":{"en":"a large group/city/area/crowd/family","cn":"大群体；大城市；大面积；一大群人；大家庭"}},{"en":"used to describe one size in a range of sizes of clothes, food, products used in the house, etc.","cn":"（服装、食品、家庭用品等）大号的","ex":{"en":"Would you like small, medium or large?","cn":"你要小号、中号，还是大号的？"}},{"en":"wide in range and involving many things","cn":"广泛的；众多的","ex":{"en":"a large and complex issue","cn":"重大而复杂的问题"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"大的；大型的","en":"A large thing or person is greater in size than usual or average.","ex":{"en":"The Pike lives mainly in large rivers and lakes","cn":"狗鱼主要生活在大江大湖中。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"大量的；很多的","en":"A large amount or number of people or things is more than the average amount or number.","ex":{"en":"The gang finally fled with a large amount of cash and jewellery","cn":"该团伙最后携大量现金和珠宝逃之夭夭。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"大型的；大规模的","en":"A large organization or business does a lot of work or commercial activity and employs a lot of people.","ex":{"en":"...a large company in Chicago","cn":"芝加哥一家大公司"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"重大的；重要的；严重的","en":"Large is used to indicate that a problem or issue which is being discussed is very important or serious.","ex":{"en":"...the already large problem of under-age drinking","cn":"已经很严重的未成年人饮酒问题"}},{"pos":"PHRASE 短语","cn":"大多数；一般；普遍","en":"You use at large to indicate that you are talking in a general way about most of the people mentioned.","ex":{"en":"I think the chances of getting reforms accepted by the community at large remain extremely remote","cn":"我看要使改革方案得到社会的广泛认可，机会还很渺茫。"}},{"pos":"PHRASE 短语","cn":"在逃的；未被捕获的","en":"If you say that a dangerous person, thing, or animal is at large, you mean that they have not been captured or made safe.","ex":{"en":"The man who tried to have her killed is still at large.","cn":"那个企图雇凶杀她的男子仍然在逃。"}},{"pos":"PHRASE 短语","cn":"大致上；总体上；总的说来","en":"You use by and large to indicate that a statement is mostly but not completely true.","ex":{"en":"By and large, the papers greet the government's new policy document with a certain amount of scepticism.","cn":"总体上，报界对政府的新政策文件将信将疑。"}},{"pos":"","cn":"","en":"to a large extent→see: ; larger than life→see: ; to loom large→see: ; in large measure→see: ;"}]},"examples":[{"en":"If we look at the larger picture of the situation, the differences seem slight.","cn":"倘若我们对情况看得全面些，这些分歧就显得微不足道了。"},{"en":"I hadn't seen her for fifteen years and then there she was, (as) large as life.","cn":"我有十五年未见过她，却在那里遇见她了，没错，就是她。"}]},"labour-saving":{"oxford":{"phon":"ˈleɪbə seɪvɪŋ","pos":"adjective","senses":[{"en":"designed to reduce the amount of work or effort needed to do something","cn":"省力的；节省劳力的；降低劳动强度的","ex":{"en":"modern labour-saving devices such as washing machines and dishwashers","cn":"诸如洗衣机和洗碗机之类的现代化省力设备"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"省力的；降低劳动强度的","en":"A labour-saving device or idea makes it possible for you to do something with less effort than usual.","ex":{"en":"...labour-saving devices such as washing machines.","cn":"洗衣机之类的省力的设备"}}]},"media":{"uk":"media/uk/labour_saving_1_gb_1.mp3","us":"media/us/labour_saving_1_us_1.mp3"},"examples":[{"en":"modern labour-saving devices such as washing machines and dishwashers","cn":"诸如洗衣机和洗碗机之类的现代化省力设备"}]},"lanes":{"lemma":"lane"},"languages":{"lemma":"language"},"lawmakers":{"lemma":"lawmaker"},"laborer":{"oxford":{"phon":"ˈleɪbərə(r)","pos":"noun","senses":[{"en":"a person whose job involves hard physical work that does not need special skills, especially work that is done outdoors","cn":"（尤指不需要特殊技术的户外劳作）体力劳动者，劳工，工人","ex":{"en":"an agricultural laborer","cn":"农业工人"}}]},"media":{"uk":"media/ldoce/hwd/bre/e/brelasdelaborer.mp3","us":"media/ldoce/hwd/ame/5/laborer.mp3"},"collins":{"senses":[{"pos":"","cn":"","en":"→see: ;"}]}},"landscaping":{"oxford":{"phon":"ˈlændskeɪpɪŋ","pos":"noun","senses":[{"en":"the process of making a garden or other piece of land more attractive by changing the design, adding features, planting trees, etc.","cn":"造景；景观美化；园林美化","ex":{"en":"Finally, in 1994, after extensive landscaping, the park was opened to the public.","cn":"经过大规模景观美化，公园最终在 1994 年对公众开放。"}},{"en":"features such as trees, stones, etc. that have been added to make a piece of land more attractive; land that has been made more attractive in this way","cn":"美化景观之物（如树木、石头等）；美化过的景观","ex":{"en":"The campus has attractive buildings and beautiful landscaping.","cn":"校园里有优美的建筑和宜人的景观。"}}]},"media":{"uk":"media/ldoce/hwd/bre/7/landscape_n0205.mp3","us":"media/ldoce/hwd/ame/4/landscape1.mp3"},"examples":[{"en":"The area around the mill pond has also been landscaped.","cn":""}],"base":"landscape"},"lamps":{"lemma":"lamp"},"lacks":{"lemma":"lack"},"landscapes":{"lemma":"landscape"},"lackluster":{"oxford":{"phon":"ˈlæklʌstə(r)","pos":"adj.","senses":[{"en":"not interesting or exciting; dull","cn":"无趣味的；单调的；枯燥乏味的"}]}},"laws":{"lemma":"law"},"lavatories":{"lemma":"lavatory"},"larger":{"lemma":"large"},"laughed":{"lemma":"laugh"},"ladders":{"lemma":"ladder"},"lasers":{"lemma":"laser"},"ladies":{"lemma":"lady"},"largest":{"lemma":"large"},"laying":{"lemma":"lay"},"lawns":{"lemma":"lawn"},"lacked":{"lemma":"lack"},"lays":{"lemma":"lay"},"lawsuit":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"诉讼；官司","en":"A lawsuit is a case in a court of law which concerns a dispute between two people or organizations.","ex":{"en":"The dispute culminated last week in a lawsuit against the government.","cn":"上周这一纠纷达到高潮，政府被告上了法庭。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a problem or complaint that a person or organization brings to a court of law to be settled","cn":"诉讼"}]},"collocations":{"phrases":["VERB + LAWSUIT bring, file, issue A lawsuit has been filed against the company. | be involved in, pursue | drop They have agreed to drop the","PREP. in a/the ~ They are seeking damages in a lawsuit. | ~ against a lawsuit against her former husband | ~ over a lawsuit over a disputed "]},"media":{"uk":"media/ldoce/hwd/bre/3/lawsuit0205.mp3","us":"media/ldoce/hwd/ame/b/lawsuit.mp3"},"examples":[{"en":"He filed a lawsuit against his record company.","cn":"他对给他录制唱片的公司提起了诉讼。"},{"en":"His lawyer filed a lawsuit against the city.","cn":"他的律师对市政府提起诉讼。"}],"oxford":{"phon":"ˈlɔːsuːt","pos":"noun","senses":[{"en":"a claim or complaint against somebody that a person or an organization can make in court","cn":"诉讼；起诉","ex":{"en":"He filed a lawsuit against his record label.","cn":"他对他的唱片公司提起了诉讼。"}}]}},"lawful":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"合法的；法律允许的；法定的","en":"If an activity, organization, or product is lawful, it is allowed by law.","ex":{"en":"It was lawful for the doctors to treat her in whatever way they considered was in her best interests","cn":"医生们采用他们认为对她最有利的方法为她治疗是合法的。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"something that is legal is allowed by law","cn":""},{"en":"actions or methods that are lawful are allowed by law, especially as compared with actions or methods that are not legal","cn":""},{"en":"legitimate activities, organizations, or claims are done or work according to, normal laws and rules","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"When something's legal, or the rules allow it, you can call it lawful . It's lawful to plant a tree in your yard, but it's not lawful to dig up a tree in the city park."}]},"collocations":{"phrases":["VERBS be | become | consider sth, deem sth","ADV. perfectly This is a perfectly lawful activity."]},"media":{"uk":"media/ldoce/hwd/bre/f/lawful0205.mp3","us":"media/ldoce/hwd/ame/1/lawful.mp3"},"examples":[{"en":"a lawfully elected government","cn":"合法选举产生的政府"},{"en":"his lawful heir","cn":"他的合法继承人"}],"oxford":{"phon":"ˈlɔːfl","pos":"adjective","senses":[{"en":"allowed or recognized by law; legal","cn":"法定的；法律承认的；合法的","ex":{"en":"his lawful heir","cn":"他的合法继承人"}}]}},"ladder":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"梯子","en":"A ladder is a piece of equipment used for climbing up something or down from something. It consists of two long pieces of wood, metal, or rope with steps fixed between them."},{"pos":"N-SING 单数名词","cn":"（社会、组织或系统中晋升或降级的）梯级，阶梯","en":"You can use the ladder to refer to something such as a society, organization, or system which has different levels that people can progress up or drop down.","ex":{"en":"If they want to climb the ladder of success they should be given that opportunity","cn":"假如他们有出人头地的意愿，就应该给他们那样的机会。"}},{"pos":"N-COUNT 可数名词","cn":"（女性长筒袜或裤袜的）抽丝，脱线","en":"A ladder is a hole or torn part in a woman's stocking or tights, where some of the vertical threads have broken, leaving only the horizontal threads.","ex":{"en":"Her hair was a mess and there was a ladder in her tights.","cn":"她头发乱糟糟，裤袜脱了线。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"to give someone who works in an organization a more important job than the one they had before","cn":""},{"en":"to move someone to another job, usually a better, more important one within the same organization","cn":""},{"en":"when someone is given a more important job in an organization","cn":""}]},"collocations":{"phrases":["ADJ. rickety | wooden | loft, rope","VERB + LADDER ascend, clamber up, climb (up), mount, go up He went up the ladder onto the deck. | come down, descend, go down | put up We pu","PREP. on/up a/the ~ She was up a ladder mending the roof. | down a/the ~ I was standing lower down the ladder. | ~ to the ladder to the gall","PHRASES the bottom/foot of a ladder, a rung/step of a ladder Several of the ladder's rungs were broken. | the top of a ladder 2 levels in a ","ADJ. evolutionary, social the people at the top of the social ladder | career, corporate, housing, promotion","VERB + LADDER ascend, climb, move up She was anxious to move up the promotion ladder. | get onto","PREP. higher up the ~ creatures higher up the evolutionary ladder | lower down the ~ | ~ of the ladder of fame | ~ to helping her on the lad","PHRASES get/have one foot on the ladder He finally managed to get one foot on the career ladder. | a rung/step on the ladder the old problem"]},"media":{"img":["media/ldoce/img/ladder.jpg","media/ldoce/img/ldoce_192.png"],"uk":"media/ldoce/hwd/bre/2/ladder_n0205.mp3","us":"media/ldoce/hwd/ame/0/ladder.mp3"},"examples":[{"en":"to move up or down the social ladder","cn":"爬上/跌下社会阶梯"},{"en":"( BrE ) to get onto the property ladder (= buy your first home)","cn":"首次进入有房阶层"}],"oxford":{"phon":"ˈlædə(r)","pos":"noun","senses":[{"en":"a piece of equipment for climbing up and down a wall, the side of a building, etc., consisting of two lengths of wood or metal that are joined together by steps or rungs","cn":"梯子","ex":{"en":"to climb up/fall off a ladder","cn":"爬上／跌下梯子"}},{"en":"a series of stages by which you can make progress in your life or career","cn":"（生活上进步或事业上晋升的）阶梯，途径","g":"[usually singular]","ex":{"en":"to move up or down the social ladder","cn":"爬上或跌下社会阶梯"}},{"en":"a long, thin hole in tights or stockings where some threads have broken","cn":"（紧身裤袜或长筒袜的）滑丝，抽丝","lab":"British English","ex":{"en":"I've got a ladder in my new tights.","cn":"我的新紧身衣里有一个梯子。"}},{"en":"a competition in a particular sport or game in which teams or players are arranged in a list and they can move up the list by defeating one of the teams or players above","cn":"升级比赛，升级游戏（将参赛者排名，胜者名次前提）","ex":{"en":"He’s third on the tennis ladder at work.","cn":"他在工作中的网球排名第三。"}},{"en":"if tights or stockings ladder or you ladder them, a long, thin hole appears in them","cn":"（紧身裤袜或长筒袜）出现滑丝，抽丝","pos":"verb"}]}},"latitude":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"纬度","en":"The latitude of a place is its distance from the equator.","ex":{"en":"In the middle to high latitudes rainfall has risen steadily over the last 20-30 years.","cn":"在过去二三十年里，中高纬度地区的降雨量持续增加。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"选择的自由；回旋余地","en":"Latitude is freedom to choose the way in which you do something.","ex":{"en":"He would be given every latitude in forming a new government","cn":"他将可以不受任何限制地组建新政府。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the distance north or south of the equator (= the imaginary line around the middle of the world ) , measured in degrees","cn":"纬度"},{"en":"an area at a particular latitude","cn":"纬度地区"},{"en":"freedom to choose what you do or say","cn":"自由度﹐选择的余地"}]},"vocab":{"pos":"1 n 2 n","senses":[{"en":"Use the word latitude to describe how much freedom you have in making choices. For example, if a teacher gives you latitude in writing your paper, you might get to choose the topic and how many sources to include."}]},"collocations":{"phrases":["ADJ. high, low | northern, southern | polar, temperate These birds only survive in temperate latitudes.","VERB + LATITUDE calculate, determine","PHRASES a line of latitude 2 freedom","ADJ. considerable, great","QUANT. degree Some degree of latitude is required in interpreting the law on this point.","VERB + LATITUDE allow (sb), give sb","PREP. ~ for This method allows very little latitude for error. | ~ in Nowadays, newspapers are allowed considerable latitude in criticizing "]},"media":{"uk":"media/ldoce/hwd/bre/e/latitude0205.mp3","us":"media/ldoce/hwd/ame/b/latitude.mp3"},"examples":[{"en":"the northern latitudes","cn":"北纬地区"},{"en":"The birds breed in northern latitudes.","cn":"这些鸟在北纬地区繁殖。"}],"oxford":{"phon":"ˈlætɪtjuːd","pos":"noun","senses":[{"en":"the distance of a place north or south of the equator (= the line around the world dividing north and south), measured in degrees","cn":"纬度","g":"[uncountable]"},{"en":"a region of the world that is a particular distance from the equator","cn":"纬度地区","g":"[plural]","ex":{"en":"the northern latitudes","cn":"北纬地区"}},{"en":"freedom to choose what you do or the way that you do it","cn":"选择（做什么事或做事方式）的自由","g":"[uncountable]","lab":"formal","ex":{"en":"Nowadays, newspapers are allowed considerable latitude in criticizing the government.","cn":"现在，报纸有相当大的批评政府的言论自由。"}}]}},"lacquer":{"collins":{"senses":[{"pos":"N-MASS 物质名词","cn":"（涂在木材或金属上的）漆","en":"Lacquer is a special liquid which is painted on wood or metal in order to protect it and to make it shiny.","ex":{"en":"We put on the second coating of lacquer","cn":"我们上了第二道漆。"}},{"pos":"N-MASS 物质名词","cn":"喷发定型剂；发胶","en":"Lacquer is a clear sticky liquid that you spray on your hair in order to hold it in place."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a liquid painted onto metal or wood to form a hard shiny surface","cn":"漆"},{"en":"hairspray","cn":"定型发胶﹐定型喷雾"},{"en":"to cover something with lacquer","cn":"给…涂漆"}]},"vocab":{"pos":"n v","senses":[{"en":"Lacquer is a clear liquid that is painted on a surface and dries hard and shiny. Lacquer can be used to protect wood."}]},"collocations":{"phrases":["ADJ. protective | clear, matt","VERB + LACQUER be coated with, be varnished with | apply, put on, spray on Apply the lacquer evenly.","LACQUER + NOUN finish"]},"media":{"uk":"media/ldoce/hwd/bre/e/lacquer_n0205.mp3","us":"media/ldoce/hwd/ame/1/lacquer1.mp3"},"examples":[{"en":"a black lacquered box","cn":"黑漆箱子"}],"oxford":{"phon":"ˈlækə(r)","pos":"noun","senses":[{"en":"a liquid that is used on wood or metal to give it a hard, shiny surface","cn":"漆"},{"en":"a liquid that is sprayed on the hair so that it stays in place","cn":"发胶；定型剂","lab":"old-fashioned"},{"en":"to cover something such as wood or metal with lacquer","cn":"给（木制品或金属）涂漆","ex":{"en":"a lacquered Chinese table","cn":"一张中国漆的桌子"},"pos":"verb"},{"en":"to put lacquer on your hair","cn":"给（头发）喷发胶","lab":"British English, old-fashioned，，","ex":{"en":"Her hair had been carefully backcombed and lacquered into shape.","cn":"她的头发被仔细地向后梳理，并上漆定形。"},"pos":"verb"}]}},"lapse":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"闪失；过失；失检","en":"A lapse is a moment or instance of bad behaviour by someone who usually behaves well.","ex":{"en":"On Friday he showed neither decency nor dignity. It was an uncommon lapse.","cn":"星期五那天他的表现既不得体，又有失尊严。如此失态非常少有。"}},{"pos":"N-COUNT 可数名词","cn":"（一时的）疏忽，大意，开小差","en":"A lapse of something such as concentration or judgment is a temporary lack of that thing, which can often cause you to make a mistake.","ex":{"en":"I had a little lapse of concentration in the middle of the race","cn":"我在比赛中途一时走神。"}},{"pos":"VERB 动词","cn":"陷入，进入（某种安静或静止状态）","en":"If you lapse into a quiet or inactive state, you stop talking or being active.","ex":{"en":"She muttered something unintelligible and lapsed into silence","cn":"她不知嘟囔了几句什么后就不再开口。"}},{"pos":"VERB 动词","cn":"（通常指短暂地）进入，陷入（某种说话或行事方式）","en":"If someone lapses into a particular way of speaking, or behaving, they start speaking or behaving in that way, usually for a short period.","ex":{"en":"She lapsed into a little girl voice to deliver a nursery rhyme","cn":"她改用童声唱起童谣来。"}},{"pos":"N-SING 单数名词","cn":"（时间的）间隔","en":"A lapse of time is a period that is long enough for a situation to change or for people to have a different opinion about it.","ex":{"en":"...the restoration of diplomatic relations after a lapse of 24 years","cn":"时隔24年后外交关系的恢复"}},{"pos":"VERB 动词","cn":"（时间）流逝，消逝，推移","en":"If a period of time lapses, it passes.","ex":{"en":"New products and production processes are transferred to the developing countries only after a substantial amount of time has lapsed.","cn":"新的产品和生产工序要经过一段相当长的时间后才能向发展中国家转移。"}},{"pos":"VERB 动词","cn":"结束；终止","en":"If a situation or legal contract lapses, it is allowed to end rather than being continued, renewed, or extended.","ex":{"en":"Her membership of the Labour Party has lapsed","cn":"她已不再是工党党员。"}},{"pos":"VERB 动词","cn":"停止信教；背弃信仰；脱离宗教关系","en":"If a member of a particular religion lapses, they stop believing in it or stop following its rules and practices.","ex":{"en":"I lapsed in my 20s, returned to it, then lapsed again, while writing the life of historical Jesus","cn":"我20多岁时曾经停止信教，后来一度又信，再后来撰写历史上耶稣的生平故事时又再脱教。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a short period of time during which you fail to do something well or properly, often caused by not being careful","cn":"疏忽﹐失误"},{"en":"a failure to do something you should do, especially to behave correctly 〔","cn":"尤指举止方面的〕疏忽﹐行为失当﹐失礼"},{"en":"a period of time between two events 〔","cn":"两个事件间的〕时间间隔"}]},"vocab":{"pos":"1 v n 2 v","senses":[{"en":"A lapse is a temporary slip, failure or break in continuity. Eating a second helping of cake when you're otherwise doing well on your diet is a lapse . Eating the whole cake in one sitting is a serious lapse in judgment."}]},"collocations":{"phrases":["ADJ. minor | momentary, temporary | sudden | memory, mental I keep suffering these mental lapses.","VERB + LAPSE have, suffer I had a momentary lapse when I couldn't remember his name.","PREP. ~ in a lapse in attention | ~ of sudden lapses of concentration 2 bad behaviour","ADJ. curious, odd It was an odd lapse for one who is normally so polite. 3 passing of time","ADJ. brief, considerable | time","PHRASES ~ of after a considerable lapse of time a time lapse of three months"]},"media":{"uk":"media/ldoce/hwd/bre/2/lapse_n0205.mp3","us":"media/ldoce/hwd/ame/2/lapse1.mp3"},"examples":[{"en":"A momentary lapse in the final set cost her the match.","cn":"她最后一盘一走神儿，输掉了整场比赛。"},{"en":"She had allowed her membership to lapse.","cn":"她的会员资格期满终止，没有再续。"}],"oxford":{"phon":"læps","pos":"noun","senses":[{"en":"a small mistake, especially one that is caused by forgetting something or by being careless","cn":"小错；（尤指）记错，过失，疏忽","ex":{"en":"a lapse of concentration/memory","cn":"心不在焉；记错"}},{"en":"a period of time between two things that happen","cn":"（两件事发生的）间隔时间","ex":{"en":"After a lapse of six months we met up again.","cn":"相隔六个月之后我们又相遇了。"}},{"en":"an example or period of bad behaviour from somebody who normally behaves well","cn":"行为失检；（平时表现不错的人一时的）失足","ex":{"en":"It was an odd lapse for one who is normally so polite.","cn":"对一个平时如此礼貌的人来说，这种闪失真是异常。"}},{"en":"to no longer be legally recognized because the period of time that it lasts has come to an end","cn":"失效；过期","g":"[intransitive]","ex":{"en":"She had allowed her membership to lapse.","cn":"她的会员资格期满终止，没有再续。"},"pos":"verb"},{"en":"to gradually become weaker or come to an end","cn":"衰退；衰弱；（逐渐）消失，结束","g":"[intransitive]","ex":{"en":"His concentration lapsed after a few minutes.","cn":"几分钟后他的注意力就下降了。"},"pos":"verb"},{"en":"to stop believing in or practising your religion","cn":"背弃，放弃（宗教信仰）","g":"[intransitive]","ex":{"en":"He lapsed from Judaism when he was a student.","cn":"他当学生时就放弃了犹太教。"},"pos":"verb"}]}},"lane":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（尤指乡间的）小径，小路","en":"A lane is a narrow road, especially in the country.","ex":{"en":"...a quiet country lane","cn":"宁静的乡间小径"}},{"pos":"N-IN-NAMES 名称名词","cn":"（用于路名）道，路，巷","en":"Lane is also used in the names of roads, either in cities or in the country.","ex":{"en":"...The Dorchester Hotel, Park Lane.","cn":"公园路多切斯特酒店"}},{"pos":"N-COUNT 可数名词","cn":"车道","en":"A lane is a part of a main road which is marked by the edge of the road and a painted line, or by two painted lines.","ex":{"en":"The lorry was travelling at 20mph in the slow lane","cn":"卡车在慢车道上以20英里的时速行驶。"}},{"pos":"N-COUNT 可数名词","cn":"泳道；跑道","en":"At a swimming pool or athletics track, a lane is a long narrow section which is marked by lines or ropes.","ex":{"en":"The pool is divided into three sections with a crawler lane for beginners","cn":"泳池分三部分，有为初学者而设的慢泳道。"}},{"pos":"N-COUNT 可数名词","cn":"航道；航线","en":"A lane is a route that is frequently used by aircraft or ships.","ex":{"en":"The collision took place in the busiest shipping lanes in the world.","cn":"撞船事故发生在全世界最繁忙的航道上。"}},{"pos":"PHRASE 短语","cn":"紧张而刺激的生活","en":"If you say that someone lives their life in the fast lane, you mean that they live in a way which seems full of activity and excitement but which often involves a lot of pressure.","ex":{"en":"...the young criminals' lust for life in the fast lane.","cn":"青少年罪犯对紧张刺激生活的贪求"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a hard surface for cars, buses etc to drive on","cn":""},{"en":"a road in a town, with houses or shops on each side","cn":""},{"en":"a road in a town, often with trees on each side","cn":""}]},"collocations":{"phrases":["ADJ. little, narrow, single-track, small | quiet | bumpy, rough | dusty, muddy | twisting, winding | grassy, green, leafy | cobbled | countr","VERB + LANE turn down/into","LANE + VERB go, lead, run the lane leading to the village The lane runs past the the lake.","PREP. along a/the ~ We cycled for miles along winding country lanes. | down a/the ~, in a/the ~, up a/the ~ 2 part of a wide road for one li","ADJ. fast, slow | inside, left-hand, middle, outside, right-hand | overtaking | northbound, southbound, etc. | traffic | bus, cycle","VERB + LANE change, get in I hate changing lanes on the motorway. Get in lane early when approaching a junction. | keep in, stay in","LANE + NOUN closures, restrictions Lane closures are causing hold-ups on the M6 near junction 2.","PREP. in (the) ~ The bus was crawling along in the slow lane."]},"media":{"uk":"media/ldoce/hwd/bre/d/lain0205.mp3","us":"media/ldoce/hwd/ame/a/lain.mp3"},"examples":[{"en":"The Australian in lane four is coming up fast from behind.","cn":"第四道的澳大利亚选手正从后面快速追赶上来。"},{"en":"The quickest way is through the back lanes behind the bus station.","cn":"最近的路是穿过公共汽车站后面的小巷。"}],"oxford":{"phon":"leɪn","pos":"noun","senses":[{"en":"a narrow road in the country","cn":"（乡间）小路","ex":{"en":"winding country lanes","cn":"蜿蜒的乡间小路"}},{"en":"a city street","cn":"（城市的）街，巷","ex":{"en":"Park Lane","cn":"帕克巷"}},{"en":"a section of a wide road, that is marked by painted white lines, to keep lines of traffic separate","cn":"车道","ex":{"en":"the inside/middle lane","cn":"内车道；中间车道"}},{"en":"a narrow marked section of a track or a swimming pool that is used by one person, for example when taking part in a race","cn":"（比赛的）跑道，泳道，球道","ex":{"en":"The Australian in lane four is coming up fast from behind.","cn":"第四道的澳大利亚选手正从后面快速追赶上来。"}},{"en":"a route used by ships or aircraft on regular journeys","cn":"航道；航线","ex":{"en":"one of the world’s busiest shipping/sea lanes","cn":"世界上最繁忙的海运航线之一"}},{"en":"(in tenpin bowling) a narrow section of floor along which the ball is bowled","cn":"（十柱保龄球）球道","ex":{"en":"a 20-lane bowling alley","cn":"有 20 条球道的保龄球馆"}}]}},"lapel":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（夹克或大衣的）翻领","en":"The lapels of a jacket or coat are the two top parts at the front that are folded back on each side and join on to the collar."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the part of the front of a coat or jacket that is joined to the collar and folded back on each side 〔","cn":"西服上衣或夹克的〕翻领"}]},"collocations":{"phrases":["ADJ. narrow, wide a coat with wide lapels","VERB + LAPEL be pinned to A silver brooch was pinned to her lapel.","LAPEL + NOUN badge, pin","PREP. in the/your ~ He was wearing a carnation in his lapel. | on the/your ~ a jacket with a badge on the lapel","PHRASES grab sb by the lapels He grabbed her by the lapels and shook her violently."]},"media":{"img":["media/ldoce/img/ldoce_195.png"],"uk":"media/ldoce/hwd/bre/e/lapel0205.mp3","us":"media/ldoce/hwd/ame/b/lapel.mp3"},"oxford":{"phon":"ləˈpel","pos":"noun","senses":[{"en":"one of the two front parts of the top of a coat or jacket that are joined to the collar and are folded back","cn":"（西服外衣或夹克上部胸前的）翻领","ex":{"en":"to wear a flower in your lapel","cn":"在你的翻领上戴一朵花"}}]}},"larder":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"食物贮藏室；食品柜","en":"A larder is a room or large cupboard in a house, usually near the kitchen, in which food is kept."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a small room or large cupboard for storing food in a house 〔","cn":"家中的〕食品贮藏室﹐食品贮藏柜"}]},"vocab":{"pos":"n","senses":[{"en":"When your mother buys groceries, she puts them in the larder or the pantry. A larder is a room or cabinet where you store food."}]},"collocations":{"phrases":["ADJ. full, well-stocked | bare, empty | walk-in","VERB + LARDER fill, stock | empty, raid He comes home from school and raids the larder.","LARDER + NOUN door, shelf","PREP. in the ~ There wasn't much food left in the larder."]},"media":{"uk":"media/ldoce/hwd/bre/d/larder0205.mp3","us":"media/ldoce/hwd/ame/8/larder.mp3"},"oxford":{"phon":"ˈlɑːdə(r)","pos":"noun","senses":[{"en":"a cupboard or small room in a house, used for storing food, especially in the past","cn":"（尤指旧时的）食物橱柜，食物贮藏室","ex":{"en":"He comes home from school and raids the larder.","cn":"他从学校回到家就冲向食品柜找吃的。"}}]}},"lame":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"跛的；瘸的","en":"If someone is lame, they are unable to walk properly because of damage to one or both of their legs.","ex":{"en":"He was aware that she was lame in one leg","cn":"他注意到她一条腿有残疾。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（借口、论点、评论等）站不住脚的；蹩脚的；拙劣的","en":"If you describe something, for example an excuse, argument, or remark, as lame, you mean that it is poor or weak.","ex":{"en":"He mumbled some lame excuse about having gone to sleep","cn":"他含含糊糊地找了个蹩脚的借口，想要解释自己为什么睡着了。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"difficult or impossible to believe","cn":""},{"en":"a story, explanation, or excuse that is unlikely cannot be believed because it is so unusual","cn":""},{"en":"a statement or event that is improbable is difficult to believe, even though it may in fact be true or may actually have happened","cn":""}]},"vocab":{"pos":"1 adj v 2 adj 3 n 4 ","senses":[{"en":"You might describe a limping dog that's lost the use of one of its legs as lame , which means \"disabled in a leg or foot.\""}]},"collocations":{"phrases":["VERBS be, look | go His horse had gone lame. | leave sb, make sb an accident which had left him lame","ADV. completely, quite | slightly"]},"media":{"uk":"media/ldoce/hwd/bre/3/brelasdelame.mp3","us":"media/ldoce/hwd/ame/5/lame1.mp3"},"examples":[{"en":"The disease has left her with permanent lameness.","cn":"那场病使她永远不能直立走路了。"},{"en":"She gave some lame excuse about missing the bus.","cn":"她找了个拙劣的借口﹐说是没有赶上公共汽车。"}],"oxford":{"phon":"leɪm","pos":"adjective","senses":[{"en":"unable to walk well because of an injury to the leg or foot","cn":"瘸的；跛的","ex":{"en":"My horse had gone lame.","cn":"我的马跛了。"}},{"en":"weak and difficult to believe","cn":"站不住脚的；无说服力的","ex":{"en":"Stephen made some lame excuse.","cn":"史蒂芬找了一些蹩脚的借口。"}},{"en":"not interesting or fun","cn":"无趣的；无聊的","ex":{"en":"The humour is more lame than funny.","cn":"这种幽默并不好笑，无趣得很。"}},{"en":"a type of cloth into which gold- or silver-coloured thread has been twisted","cn":"金银锦缎","ex":{"en":"a silver lamé evening gown","cn":"银色金属丝晚礼服"},"pos":"noun"}]}},"lay-by":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"路侧停车带","en":"A lay-by is a short strip of road by the side of a main road, where cars can stop for a while.","ex":{"en":"I left my car in a lay-by and set off on foot.","cn":"我把车留在路侧停车带，徒步而行。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a space next to a road where vehicles can stop","cn":"路侧停车带"}]},"collocations":{"phrases":["PREP. in a/the ~ I was parked in a lay-by, having a nap."]},"media":{"uk":"media/ldoce/hwd/bre/e/lay_by0205.mp3","us":"media/ldoce/hwd/ame/3/ld41lay-by.mp3"},"examples":[{"en":"You could secure it on lay-by.","cn":"你可以预付订金方式购买此货。"}],"oxford":{"phon":"ˈleɪ baɪ","pos":"noun","senses":[{"en":"an area at the side of a road where vehicles may stop for a short time","cn":"路边临时停车处；路侧停车带","g":"[countable]","lab":"British English","ex":{"en":"He pulled into the lay-by and got out to see what was wrong with the car.","cn":"他把车停进停车路口，下车看看车出了什么问题。"}},{"en":"a system of paying some money for an article so that it is kept for you and you can pay the rest of the money later","cn":"预付订金购买","g":"[uncountable, countable]","lab":"Australian English, New Zealand English, South African English，，，，","ex":{"en":"You could secure it on lay-by.","cn":"你可以预付订金方式购买此货。"}}]}},"lavatory":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"同toilet","en":"A lavatory is the same as a toilet .","ex":{"en":"...the ladies' lavatory at the University of London.","cn":"伦敦大学的女厕所"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a room with a toilet in it, in someone’s house or in a public place","cn":""},{"en":"a room with a toilet in it, in someone’s house. In British English, bathroom is used especially when you want to be polite. In American English, it is the usual word to use","cn":""},{"en":"a room in a public place that has one or more toilets in it","cn":""}]},"collocations":{"phrases":["ADJ. public | communal, shared | indoor, inside | outside | flush, flushing","VERB + LAVATORY go to, use | need | flush, flush sth down","LAVATORY + NOUN basin, bowl | seat | cistern | chain | paper | brush","PREP. in the ~, on the ~"]},"media":{"uk":"media/ldoce/hwd/bre/d/lavatory0205.mp3","us":"media/ldoce/hwd/ame/9/lavatory.mp3"},"examples":[{"en":"The nearest public lavatory is at the station.","cn":"最近的公共厕所在车站。"},{"en":"There's a bathroom and a lavatory upstairs.","cn":"楼上有浴室和卫生间。"}],"oxford":{"phon":"ˈlævətri","pos":"noun","senses":[{"en":"a toilet, or a room with a toilet in it","cn":"抽水马桶；厕所；卫生间；洗手间；盥洗室","lab":"especially British English","ex":{"en":"There's a bathroom and a lavatory upstairs.","cn":"楼上有浴室和卫生间。"}},{"en":"a public building or part of a building, with toilets in it","cn":"公共厕所（或卫生间、洗手间、盥洗室）","lab":"British English","ex":{"en":"The nearest public lavatory is at the station.","cn":"最近的公共厕所在车站。"}}]}},"lash":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"睫毛","en":"Your lashes are the hairs that grow on the edge of your upper and lower eyelids.","ex":{"en":"...sombre grey eyes, with unusually long lashes","cn":"一双忧郁的灰眼睛，眼睫毛长得出奇"}},{"pos":"VERB 动词","cn":"绑紧；扎牢","en":"If you lash two or more things together, you tie one of them firmly to the other.","ex":{"en":"Secure the anchor by lashing it to the rail","cn":"把锚系到栏杆上拴牢。"}},{"pos":"VERB 动词","cn":"（风、雨或水）猛抽，狠打，狂扫","en":"If wind, rain, or water lashes someone or something, it hits them violently.","ex":{"en":"The worst winter storms of the century lashed the east coast of North America","cn":"本世纪最恶劣的冬季暴风雪横扫北美东海岸。"}},{"pos":"VERB 动词","cn":"怒斥；严责；猛烈抨击","en":"If someone lashes you or lashes into you, they speak very angrily to you, criticizing you or saying you have done something wrong.","ex":{"en":"She went quiet for a moment while she summoned up the words to lash him","cn":"她沉默片刻，寻思着抨击他的话语。"}},{"pos":"N-COUNT 可数名词","cn":"鞭梢；鞭端皮条","en":"A lash is a thin strip of leather at the end of a whip."},{"pos":"N-COUNT 可数名词","cn":"（尤指作为惩罚抽在背部的）鞭打","en":"A lash is a blow with a whip, especially a blow on someone's back as a punishment.","ex":{"en":"The villagers sentenced one man to five lashes for stealing a ham from his neighbor.","cn":"村民们裁定将一名偷邻居火腿的男子鞭打5下。"}},{"pos":"VERB 动词","cn":"鞭打；抽打","en":"If someone lashes another person, they hit that person with a whip.","ex":{"en":"They snatched up whips and lashed the backs of those who had fallen.","cn":"他们抓起鞭子，朝跌倒的人背上抽去。"}},{"pos":"V-ERG 及物/不及物动词","cn":"（使）（尾巴）急速挥动","en":"If an animal lashes its tail, or if its tail lashes, it moves its tail very fast and violently.","ex":{"en":"When in danger, the anteater lashes its tail round a branch","cn":"遇有危险，食蚁兽会迅速用尾巴卷住树枝。"}},{"pos":"","cn":"","en":"相关词组：lash out"}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to fasten one thing to another using rope, string, wire etc","cn":""},{"en":"to tie things together so that they are held firmly together","cn":""},{"en":"to tie or fasten something, especially a piece of clothing","cn":""}]},"collocations":{"phrases":["ADJ. bottom, lower | long, thick","VERB + LASH bat, flutter She batted her lashes flirtatiously. | lower She lowered her lashes in sudden embarrassment.","LASH + VERB flicker, flutter Her lashes flickered and I knew she was lying."]},"media":{"uk":"media/ldoce/hwd/bre/0/lash_n0205.mp3","us":"media/ldoce/hwd/ame/d/lash1.mp3"},"examples":[{"en":"In a bitter article he lashed out at his critics.","cn":"他写了一篇尖刻的文章，猛烈驳斥批评他的人。"},{"en":"During the storm everything on deck had to be lashed down.","cn":"暴风雨中甲板上所有的东西都必须系牢。"}],"oxford":{"phon":"læʃ","pos":"verb","senses":[{"en":"to hit somebody/something with great force","cn":"猛击；狠打","g":"[intransitive, transitive]","ex":{"en":"The rain lashed at the windows.","cn":"雨点猛烈地打在窗户上。"}},{"en":"to hit a person or an animal with a whip, rope, stick, etc.","cn":"鞭打；抽打","g":"[transitive]"},{"en":"to criticize somebody/something in a very angry way","cn":"怒斥","g":"[transitive]"},{"en":"to fasten something tightly to something else with ropes","cn":"捆绑；捆扎","g":"[transitive]","ex":{"en":"Several logs had been lashed together to make a raft.","cn":"几根原木捆扎在一起做成了木筏。"}},{"en":"to move or to move something quickly and violently from side to side","cn":"（使）迅猛摆动，甩动","g":"[intransitive, transitive]","ex":{"en":"The crocodile's tail was lashing furiously from side to side.","cn":"鳄鱼的尾巴在急速地左右甩动。"}},{"en":"one of the hairs growing on the edge of the eyelids","cn":"睫；睫毛","g":"[usually plural]","ex":{"en":"her long dark lashes","cn":"她那长长的黑睫毛"},"pos":"noun"},{"en":"a hit with a whip, given as a form of punishment","cn":"（作为惩罚的）鞭打，抽打","lab":"figurative","ex":{"en":"They each received 20 lashes for stealing.","cn":"他们因盗窃每人挨了 20 鞭。"},"pos":"noun"},{"en":"the thin leather part at the end of a whip","cn":"鞭端皮条；鞭梢","ex":{"en":"The lash struck him across the back.","cn":"鞭子打在他的背上。"},"pos":"noun"}]}},"lancashire":{"ldoce":{"phon":"hwd","pos":"","senses":[{"en":"a county in northwest England, which was once the centre of the cotton industry in the UK and had many factories that produced cloth. The large cities of Liverpool and Manchester were formerly part of Lancashire, but now form their own local government areas. ","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/6/p028-000007155.mp3","us":"media/ldoce/hwd/ame/9/lancashire_.mp3"},"oxford":{"phon":"ˈlænkəʃə(r)","pos":"","senses":[{"en":"a county in north-west England. It was one of the centres of the Industrial Revolution, and was famous especially for its cotton mills and coal mines. In 1974 the county was reduced in size and it no longer includes the cities of Liverpool and Manchester. Its administrative centre is Preston.","cn":"兰开夏郡：英格兰西北部的一个县。它是工业革命的中心之一，尤其以棉纺厂和煤矿而闻名。1974年，该县规模缩小，不再包括利物浦和曼彻斯特市。它的行政中心是普雷斯顿。"},{"en":"a type of mild white cheese that breaks easily into small pieces. It is traditionally made in Lancashire.","cn":"兰开夏郡（Lancashire）：一种淡淡的白色奶酪，容易分解成小块。传统上，它是在兰开夏郡（Lancashire）制造的。","g":"[uncountable]"}]}},"laden":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"装满的；满载的","en":"If someone or something is laden with a lot of heavy things, they are holding or carrying them.","ex":{"en":"I came home laden with cardboard boxes","cn":"我抱着一大堆纸箱回了家。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"充满…的；饱受…的","en":"If you describe a person or thing as laden with something, particularly something bad, you mean that they have a lot of it.","ex":{"en":"We're so laden with guilt","cn":"我们深感愧疚。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"heavily loaded with something, or containing a lot of something","cn":"装满的﹐满载的"},{"en":"having a lot of a particular quality, thing etc","cn":"充满〔某种品质﹑东西等〕的"}]},"vocab":{"pos":"1 adj v 2 adj v","senses":[{"en":"Something that is laden is weighted down by something heavy, like an apple tree that's laden with fruit."}]},"collocations":{"phrases":["VERBS be","ADV. heavily He took the heavily laden tray from her. | absolutely, fully The trees were absolutely laden with apples. a fully laden basket","PREP. with They arrived laden with gifts."]},"media":{"uk":"media/ldoce/hwd/bre/c/laden0205.mp3","us":"media/ldoce/hwd/ame/5/laden.mp3"},"examples":[{"en":"His voice was soft, yet laden with threat.","cn":"他说话的声音很柔和，但充满了恐吓的语气。"},{"en":"The trees were laden with apples.","cn":"树上都挂满了苹果。"}],"oxford":{"phon":"ˈleɪdn","pos":"adjective","senses":[{"en":"heavily loaded with something","cn":"载满的；装满的","ex":{"en":"passengers laden with luggage","cn":"携带大批行李的旅客"}},{"en":"full of something, especially something unpleasant","cn":"充满的（尤指充满令人不快的东西）","lab":"literary","ex":{"en":"His voice was soft, yet laden with threat.","cn":"他说话的声音很柔和，但充满了恐吓的语气。"}},{"en":"used to form adjectives showing that something is full of, or loaded with, the thing mentioned","cn":"（用于构成形容词）充满…的，装载…的","ex":{"en":"calorie-laden cream cakes","cn":"高热量的奶油蛋糕"}}]}},"laser":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"激光","en":"A laser is a narrow beam of concentrated light produced by a special machine. It is used for cutting very hard materials, and in many technical fields such as surgery and telecommunications.","ex":{"en":"...new laser technology","cn":"新的激光技术"}},{"pos":"N-COUNT 可数名词","cn":"激光器","en":"A laser is a machine that produces a laser beam.","ex":{"en":"...the first-ever laser, built in 1960.","cn":"有史以来第一台激光器，于1960年制造"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a piece of equipment that produces a powerful narrow beam of light that can be used in medical operations, to cut metals, or to make patterns of light for entertainment","cn":"激光器"},{"en":"a beam of light produced by a laser","cn":"激光"}]},"vocab":{"pos":"n","senses":[{"en":"A laser is a focused beam of light used for many reasons, from eye surgery to gun scopes to laser pointers."}]},"collocations":{"phrases":["ADJ. powerful","VERB + LASER use","LASER + NOUN beam, light | printer | gun | surgery, therapy, treatment"]},"media":{"uk":"media/ldoce/hwd/bre/d/laser0205.mp3","us":"media/ldoce/hwd/ame/d/laser.mp3"},"examples":[{"en":"The barcodes on the products are read by lasers.","cn":"产品上的条码是用激光读取的。"},{"en":"She's had laser surgery on her eye.","cn":"她做了眼部激光手术。"}],"oxford":{"phon":"ˈleɪzə(r)","pos":"noun","senses":[{"en":"a device that gives out light in which all the waves oscillate (= change direction and strength) together, typically producing a powerful beam of light that can be used for cutting metal, in medical operations, etc.","cn":"激光器","ex":{"en":"a laser beam","cn":"激光束"}}]}},"lag":{"collins":{"senses":[{"pos":"VERB 动词","cn":"落后；赶不上","en":"If one thing or person lags behind another thing or person, their progress is slower than that of the other.","ex":{"en":"Britain still lags behind most of Europe in its provisions for women who want time off to have babies","cn":"英国在妇女生育福利方面依然落后于欧洲大多数国家。"}},{"pos":"N-COUNT 可数名词","cn":"间隔；间歇；时间差","en":"A time lag or a lag of a particular length of time is a period of time between one event and another related event.","ex":{"en":"There's a time lag between infection with HIV and developing AIDS","cn":"从感染艾滋病病毒到病发有一段滞后期。"}},{"pos":"VERB 动词","cn":"给（屋顶、水管或水箱）装绝热层","en":"If you lag the inside of a roof, a pipe, or a water tank, you cover it with a special material in order to prevent heat escaping from it or to prevent it from freezing.","ex":{"en":"If you have to take the floorboards up, take the opportunity to lag any pipes at the same time","cn":"如果一定要把地板掀开，不妨趁此机会给各个管道加一层隔热保护。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to move more slowly than the other people you are with, so that you become separated from them","cn":""},{"en":"to walk or move more slowly than other people in the group you are with","cn":""},{"en":"to move or develop more slowly than others","cn":"落后(于)﹐拖后"}]},"vocab":{"pos":"1 v n 2 n 3 v 4 v 5 ","senses":[{"en":"When you can't keep up with your fellow marathon runners, you can say that you lag behind them."}]},"collocations":{"phrases":["ADV. badly, seriously | behind She did well in her first year at school but then started to lag behind.","PREP. behind Britain still lags badly behind the rest of Europe on this.","PHRASES lag far/way/well behind (sb/sth) The Tories are still lagging way behind in the opinion polls."]},"media":{"uk":"media/ldoce/hwd/bre/0/lag_v0205.mp3","us":"media/ldoce/hwd/ame/9/lag1.mp3"},"examples":[{"en":"We still lag far behind many of our competitors in using modern technology.","cn":"我们在运用现代技术方面仍然远远落后于我们的许多竞争对手。"},{"en":"The little boy lagged behind his parents.","cn":"那小男孩落在了父母的后面。"}],"oxford":{"phon":"læɡ","pos":"verb","senses":[{"en":"to move or develop slowly or more slowly than other people, organizations, etc.","cn":"缓慢移动；发展缓慢；滞后；落后于","g":"[intransitive]","ex":{"en":"The little boy lagged behind his parents.","cn":"那小男孩落在了父母的后面。"}},{"en":"to cover pipes, etc. with a special material to stop the water in them from freezing, or to stop heat from escaping","cn":"给（管道等）加防冻保暖层","g":"[transitive]","lab":"British English"},{"en":"the period of time between two connected events","cn":"（两件相关事件的）时间间隔，时滞","pos":"noun"}]}},"landslide":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（选举中）大获全胜，一面倒的胜利","en":"A landslide is a victory in an election in which a person or political party gets far more votes or seats than their opponents.","ex":{"en":"He won last month's presidential election by a landslide","cn":"他以压倒性多数赢得上月的总统选举。"}},{"pos":"N-COUNT 可数名词","cn":"塌方；山崩；滑坡","en":"A landslide is a large amount of earth and rocks falling down a cliff or the side of a mountain.","ex":{"en":"The storm caused landslides and flooding in Savona.","cn":"风暴致使萨沃纳发生塌方和洪灾。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a situation in which you win a battle, game, election, or dispute","cn":""},{"en":"a victory in a sports game or in a competition","cn":""},{"en":"an important victory, especially in war or politics","cn":""}]},"collocations":{"phrases":["VERB + LANDSLIDE cause The floods caused a landslide.","LANDSLIDE + VERB destroy sth The village was destroyed by a landslide. 2 election victory","ADJ. electoral Nobody predicted such an electoral landslide. | Conservative, Labour, etc.","VERB + LANDSLIDE win by The National Party won by a landslide.","LANDSLIDE + NOUN victory"]},"media":{"uk":"media/ldoce/hwd/bre/a/landslide0205.mp3","us":"media/ldoce/hwd/ame/1/landslide.mp3"},"examples":[{"en":"She was expected to win by a landslide.","cn":"预计她会以压倒多数的选票获胜。"},{"en":"a landslide victory","cn":"压倒性优势的选举胜利"}],"oxford":{"phon":"ˈlændslaɪd","pos":"noun","senses":[{"en":"a mass of earth, rock, etc. that falls down the slope of a mountain or a cliff","cn":"（山坡或悬崖的）崩塌，塌方，滑坡，地滑","ex":{"en":"The house was buried beneath a landslide.","cn":"房子被山体滑坡掩埋了。"}},{"en":"an election in which one person or party gets very many more votes than the other people or parties","cn":"一方选票占压倒多数的选举；一方占绝对优势的选举","lab":"especially North American English","ex":{"en":"She was expected to win by a landslide.","cn":"预计她会以压倒多数的选票获胜。"}}]}},"landing":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"楼梯平台","en":"In a house or other building, the landing is the area at the top of the staircase which has rooms leading off it.","ex":{"en":"I ran out onto the landing.","cn":"我冲出去到了楼梯口。"}},{"pos":"N-VAR 可变名词","cn":"着陆；降落","en":"A landing is an act of bringing an aircraft or spacecraft down to the ground.","ex":{"en":"I had to make a controlled landing into the sea","cn":"我只好将飞机迫降在海上。"}},{"pos":"N-COUNT 可数名词","cn":"（军队的）登陆","en":"When a landing takes place, troops are unloaded from boats or aircraft at the beginning of a military invasion or other operation.","ex":{"en":"American forces have begun a big landing.","cn":"美军已开始大规模登陆。"}},{"pos":"N-COUNT 可数名词","cn":"同landing stage","en":"A landing is the same as a landing stage ."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the action of bringing an aircraft down to the ground after being in the air","cn":"着陆﹔降落"},{"en":"the floor at the top of a set of stairs or between two sets of stairs","cn":"楼梯平台"},{"en":"the action of bringing soldiers onto land that is controlled by the enemy 〔","cn":"军队的〕登陆"}]},"collocations":{"phrases":["ADJ. abrupt, bumpy | crash, emergency, forced | gentle, safe, smooth, soft","VERB + LANDING make The pilot had to make an emergency landing in a field.","LANDING + NOUN strip 2 top of a staircase","ADJ. first-floor, second-floor, etc.","PREP. off the ~ The room opens off the landing. | on the ~ There's a phone on the landing outside your room."]},"media":{"uk":"media/ldoce/hwd/bre/d/landing_las3_br.mp3","us":"media/ldoce/hwd/ame/b/landing.mp3"},"examples":[{"en":"The pilot was forced to make an emergency landing.","cn":"飞行员被迫紧急着陆。"},{"en":"the first Apollo moon landing","cn":"阿波罗航天飞船首次登月着陆"}],"oxford":{"phon":"ˈlændɪŋ","pos":"noun","senses":[{"en":"an act of bringing an aircraft or a spacecraft down to the ground after a journey","cn":"降落；着陆","g":"[countable, uncountable]","ex":{"en":"a perfect/smooth/safe landing","cn":"准确／顺利／安全着陆"}},{"en":"the area at the top of a set of stairs where you arrive before you go into an upstairs room or move onto another set of stairs","cn":"楼梯平台；（两段楼梯间的）过渡平台","g":"[countable]","ex":{"en":"Go up to the first-floor landing and it’s the door on the right.","cn":"上一楼平台，右边是门。"}},{"en":"an act of bringing soldiers to land in an area that is controlled by the enemy","cn":"登陆","g":"[countable]"},{"en":"a flat wooden platform on the water where boats let people get on and off, and load and unload goods","cn":"码头；浮动码头；栈桥","g":"[countable]","lab":"British English also"}]},"base":"land"}});
